window.TIMELINE={"title":"Horaghfus Evreni — Tam Zaman Çizelgesi","count":166,"eras":[{"id":"kadim","name":"Kadim Çağ","sub":"Kadim Tanrılar ve Keder Yağışları","from":1,"to":15},{"id":"kanunsuz","name":"Kanunsuz Dönem","sub":"Işık Elfleri ve Manayutan Baskınları","from":16,"to":19},{"id":"kurtulus","name":"Kurtuluş ve Krallıklar Çağı","sub":"Horaghfus Savaşı’ndan Dwarrebanih’e","from":20,"to":39},{"id":"gunes","name":"Güneş Savaşları Çağı","sub":"Ejderhalar, Hobbitler ve Khotekx","from":40,"to":61},{"id":"imparatorluk","name":"İmparatorluk Çağı","sub":"Aidiyet Savaşları’ndan Akademinin Çöküşüne","from":62,"to":97},{"id":"koken","name":"Arkwright Kökeni","sub":"Oyun öncesi","from":98,"to":100},{"id":"donus","name":"9902 — Boraldmir’in Dönüşü","sub":"Büyük Savaş ve yeni dönem","from":101,"to":104},{"id":"cilt1","name":"Cilt I","sub":"Sedonia’dan kırmızı kumlara","from":105,"to":120},{"id":"ts1","name":"TimeSkip 1","sub":"Beyaz oda, omurga ve Julius","from":121,"to":125},{"id":"ts2","name":"TimeSkip 2 — Crownforge","sub":"Kış, sinomorph’lar ve Seraphim","from":126,"to":139},{"id":"dusus","name":"Balahnur’un Düşüşü","sub":"Kıyamet gecesi ve büyük tahliye","from":140,"to":148},{"id":"tahliye","name":"Mital Alari’ye Varış","sub":"Elf şehri sahili","from":149,"to":154},{"id":"elfadasi","name":"Mital Alari — ElfAdası","sub":"Yeniden kuruluş","from":155,"to":160},{"id":"julius","name":"Julius’un Düşüşü","sub":"12 şarkı ve sessiz ses","from":161,"to":166}],"events":[{"o":1,"date":"1949","big":"1949","num":true,"title":"Kadim Tanrılar Tarikatı Ayini","desc":"Kadim Tanrıların geri dönmesini amaçlayan Güneyli medeniyetlerin \"An'kabar\"ı yani imparatoru olan Jihkari çok ırklı bir tarikat kurulmasını emretti. Kurulan tarikat çeşitli ayinlerle Kadim Tanrıları geri getirmeye çalıştı. Son ayin için yükseldikçe çevresi küçülen dokuzgen bir yapı inşa edildi. Ayini yapan tarikat rahipleri \"Doğuya!\" cevabını aldıktan kısa süre sonra bilinmeyen nedenlerden öldü.","chars":["An'kabar Jihkari"],"places":["Güney Toprakları"],"factions":["Kadim Tanrılar Tarikatı","Güneyliler"],"cons":"Ayini yapan rahipler 'Doğuya!' cevabını aldıktan kısa süre sonra bilinmeyen nedenlerle ölür. Bu cevap Jihkari'yi Elflere saldırmaya (1961) iter; dokuzgen yapı sonra onun mezarı olur.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":{"src":"assets/art/48_GuneyTopraklari.webp","w":1280,"h":720,"kind":"user"}},{"o":2,"date":"1951","big":"1951","num":true,"title":"Ölüm'ün Horaghfus'a inişi","desc":"Tek gecede her soylu krala giderek Ölüm ilk defa kendini gösterdi. Hepsine ne işe yaradığını bilmedikleri bir taş verdi ve ölene dek saklamalarını söyleyip sorulan hiçbir soruya cevap vermeden gitti.","chars":["Ölüm"],"places":["Horaghfus"],"factions":["Soylu krallar"],"cons":"Ölüm ilk kez görünür ve her soylu krala ne işe yaradığı bilinmeyen bir taş verir. Bu taşlar sonradan ölen asillerin geri dönmesini sağlar (2799). Kampanyada Ölüm'ün taş sürükleyerek doğuya yürümesi bu mirasla bağlantılı.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":null},{"o":3,"date":"1961","big":"1961","num":true,"title":"Güneyli-Elf Savaşı","desc":"\"Doğuya!\" cevabını alan An'kabar Jihkari, Elflerin bir şey sakladığını düşünerek onlara saldırdı. Elf büyücüleri ile Güneyli büyücüler hünerlerini sergilerken iki tarafın orduları kanlı bir savaş gerçekleştirdi. Güneyliler ikmal yetersizliğinden savaşı kaybetti.","chars":["An'kabar Jihkari"],"places":["Elf kıtası","Güney Toprakları"],"factions":["Güneyliler","Elfler"],"cons":"Güneyliler ikmal yetersizliğinden savaşı kaybeder; Jihkari'nin bozgunu daha sonra kendisini tanrılarca cezalandırılmış sanmasına yol açar.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":null},{"o":4,"date":"1971","big":"1971","num":true,"title":"Hayvanların Büyük Göçü","desc":"Bir sabah göç etme imkanı olan her hayvan Horaghfus'tan kaçarcasına göç etmeye başladı. İnsanlar kıtlık olacağını öngörüp çok sayıda yenilebilir hayvanı avlayıp etlerini sonra tüketmek üzere kuruttular.","chars":[],"places":["Horaghfus"],"factions":["İnsanlar"],"cons":"Hayvanlar topluca Horaghfus'tan göç eder; insanlar kıtlık öngörüp çok sayıda hayvanı avlayıp etlerini kurutur. Yaklaşan felaketlerin ilk işareti.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":null},{"o":5,"date":"1981","big":"1981","num":true,"title":"20 Yıllık Kuraklık","desc":"Güneyden esen sıcak rüzgarlar şiddetini arttırarak kuraklığa sebep oldu. Druidler ve Entler yeşil hayatı korumak için 20 yıl boyunca çaba gösterdi.","chars":[],"places":["Horaghfus"],"factions":["Druidler","Entler"],"cons":"Güneyden esen sıcak rüzgârlar kuraklığa yol açar; druidler ve Entler 20 yıl boyunca yeşil hayatı korumaya çalışır. Kuraklığın ardından Keder Yağışları gelir.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":null},{"o":6,"date":"2001","big":"2001","num":true,"title":"KEDER YAĞIŞLARI (başlangıç)","desc":"20 yıl kuraklıktan sonra yağış sonunda başladı; herkes kutladı. Günler, haftalar, aylar geçti, yağışlar durmadı. Kışa gelince yağmur yerini kara bıraktı. Her ırktan bitki ve hayvan soğuktan donarak öldü. Anılarına anıtlar dikildi, dualar edildi, her büyü ve büyülü eşya denendi ancak yağışlar durmadı. Düşük rakımlı yerler karlar altında kalmaya başladı. Mana ile bağlantısı olan herkes ısınmak için ateş büyüleri öğrenmeye çalıştı; büyü bilmeyenler için hayat çok daha zorlaştı. Her krallık halkına yardım etmeye çalıştı ve birbiriyle savaşmayı kesti.","chars":[],"places":["Horaghfus"],"factions":["Tüm krallıklar"],"cons":"Bin yıl sürecek Keder Yağışları başlar: bitki ve hayvanlar donar, alçak yerler karla kaplanır, büyü bilmeyenler için hayat çok zorlaşır; krallıklar birbiriyle savaşmayı bırakır.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":null},{"o":7,"date":"2021","big":"2021","num":true,"title":"Güney medeniyetlerinin çöküşü","desc":"Güneydeki krallıklara hükmeden An'kabar Jihkari, Elflere karşı yaşadığı bozgundan sonra toparlanmaya çalışıyordu ama sıcak iklimli toprakların hakimi olmasına rağmen kar yağışı onun krallığı için de gelmişti ve Güneylileri çok daha kötü vurdu. Yaptırdığı ayin aklına geldi ve savaşı başaramadığı için tanrıların onu cezalandırdığını düşünerek ayin için yaptırdığı dokuzgen yapıyı kendi mezarı haline getirtti ve ölene dek orada kaldı. Böylece son Tiefling An'kabar da Horaghfus'tan silindi. An'kabar'ın yok oluşu Güneylilerin de yok olmasına neden oldu.","chars":["An'kabar Jihkari"],"places":["Güney Toprakları"],"factions":["Güneyliler","Tiefling hanedanı"],"cons":"Son Tiefling An'kabar ölür ve Güneylilerin medeniyeti yok olur; ayin için yapılan dokuzgen yapı onun mezarı olur. (Kampanyadaki Güney kapsülleri ve Katip Pirdeviz bu mirasın izleri.)","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":null},{"o":8,"date":"2049","big":"2049","num":true,"title":"İnsan Krallıklarının çöküşü","desc":"Zaten yeni krallıklaşmış insan ırkı bu felakete karşı koyamayıp krallıklarını kaybetti.","chars":[],"places":["Horaghfus"],"factions":["İnsan krallıkları"],"cons":"Yeni krallıklaşmış insan ırkı Keder Yağışları felaketine dayanamayıp krallıklarını kaybeder.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":null},{"o":9,"date":"2059","big":"2059","num":true,"title":"Manayutanların ortaya çıkışı","desc":"Yeryüzünde tek bir karsız kara parçası kalmamışken yokluktan altı kollu, dört ayaklı, büyük ağızlı yaratıklar çıkageldi. Özellikle Mana bağlantısına sahip canlılara tetiklenen bu yaratıkların derisi, büyü sayesinde üretilmiş her şeyi emerek büyüleri etkisiz kılıyordu. Karda çok hızlı hareket edebiliyorlardı.","chars":[],"places":["Horaghfus"],"factions":["Manayutanlar"],"cons":"Büyüyü emen Manayutanlar bin yıl sürecek bir tehdit olur; Elf krallıkları (2066) ve diğer medeniyetler onların yüzünden çöker. Soyları ancak 3050'de tükenir.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":null},{"o":10,"date":"2066","big":"2066","num":true,"title":"Elf Krallıklarının çöküşü","desc":"Manayutanlar Mana bağlantısı olan canlılara saldırıp büyüleri emerken Elfler en büyük silahları olan büyüyle karşılık veremedi. Yağışların da etkisiyle Elf krallıkları birer birer düştü.","chars":[],"places":["Elf kıtası"],"factions":["Elf krallıkları","Manayutanlar"],"cons":"Elfler krallıklarını kaybeder; elf medeniyeti uzun süre yeraltına ve dağınık topluluklara çekilir.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":null},{"o":11,"date":"2081","big":"2081","num":true,"title":"Keskinayazların ortaya çıkışı","desc":"Kar fırtınasında düzenli olarak keşif yapan cüceler onlara neyin saldırdığını göremeden katledildi. Sadece kar fırtınalarında ortaya çıkan aşırı hızlı ve kar fırtınasında görünmez olan bir yaratık türü keşifleri imkansıza yakın hale getirdi.","chars":[],"places":["Horaghfus"],"factions":["Keskinayazlar","Cüceler"],"cons":"Kar fırtınalarında görünmez, aşırı hızlı yaratıklar yüzünden keşifler neredeyse imkânsız hâle gelir.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":null},{"o":12,"date":"2090","big":"2090","num":true,"title":"Sivritılsım Savaşı","desc":"Oluşan sert şartlara karşı cüceler madenlerde toplanarak silahlarda kullanılan bir tılsım dövdü. Keskinayazlara karşı büyük avantaj sağlayan bu tılsım Manayutanların cücelere odaklanmasına sebep oldu.","chars":[],"places":["Cüce madenleri"],"factions":["Cüceler","Keskinayazlar","Manayutanlar"],"cons":"Cücelerin dövdüğü tılsım Keskinayazlara karşı büyük avantaj sağlar, ancak Manayutanların cücelere odaklanmasına yol açar.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":null},{"o":13,"date":"2117","big":"2117","num":true,"title":"Kutsal Elmanın kaybı","desc":"Kutsal Elmayı taşıyan Abdiel isimli koruyucu şövalye Keskinayazlarla savaşırken öldü. Keskinayazların hedefi elma değildi; bu yüzden elma yeryüzünde bir buzun içinde kaldı.","chars":["Abdiel"],"places":["Horaghfus"],"factions":["Keskinayazlar"],"cons":"Kutsal Elma bir buzun içinde kaybolur. (Kampanyada Herkenoff malikânesindeki buzdan bir 'keskinayaz' ve hastalık çıkacak; Elma sonraki çağlarda yeniden ortaya çıkıp Narnold soyunun ve İmparatorluğun simgesi olur.)","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":null},{"o":14,"date":"2119","big":"2119","num":true,"title":"Cüce klanlarının dağılması","desc":"Manayutanlara karşı direnemeyen cüceler Strömbah dağına kaçarak Dempur madenini kurdular ve o başarısız savunmadan sonra uzun süre yeryüzüne çıkmadılar.","chars":[],"places":["Strömbah dağı","Dempur madeni"],"factions":["Cüce klanları","Manayutanlar"],"cons":"Cüceler Dempur madenini kurar ve uzun süre yeryüzüne çıkmaz.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":null},{"o":15,"date":"2125","big":"2125","num":true,"title":"Karasırt, Tor'araf ve Yemin isimli yeraltı şehirlerinin kurulması","desc":"Yeryüzünde yaşayamayan ırklar yeraltını kazarak yeni şehirler inşa etti. Şehirler genel olarak ticaret yapmak ya da asillerin kalması için kullanılırken sivil halk yeraltında tünellerde ya da oyuklarda küçük topluluklar halinde yaşadı.","chars":[],"places":["Karasırt","Tor'araf","Yemin"],"factions":["Horaghfus asilleri"],"cons":"Ticaret ve asiller için yeraltı şehirleri kurulur; sivil halk tünellerde küçük topluluklar hâlinde yaşamaya başlar. Bu şehirler 2799'da Manayutanlarca yok edilecektir.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kadim","tier":"antik","img":null},{"o":16,"date":"2130–3000","big":"2130–3000","num":true,"title":"KANUNSUZ DÖNEM","desc":"Bu dönemde devletler olmadığı için 3 ana şehir ve Dempur madeni hariç her yer kıyamet sonrasından çıkmış gibi tehlikelerle doluydu.","chars":[],"places":["Horaghfus","Dempur madeni"],"factions":[],"cons":"Devletlerin olmadığı, 3 ana şehir ve Dempur madeni dışında her yerin kıyamet sonrası gibi tehlikeli olduğu uzun bir kanunsuzluk çağı başlar (3000'e kadar).","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kanunsuz","tier":"antik","img":null},{"o":17,"date":"2370","big":"2370","num":true,"title":"Işık Elflerinin ortaya çıkışı","desc":"Güneş ışığı girmediği ve hava soğuk olduğu için tarım imkansızdı ve bilinen büyüler yeterli kalmıyordu. High Elf'ler yeni büyüler ararken bazılarının farklı büyüler yapabildiği keşfedildi. Denemeler sonucunda High Elf'lere tıpatıp benzeyen, hatta farkını anlamak imkansıza yakın bir Elf ırkı keşfedildi. Bu ırka yeni tarz büyü olan ışık büyülerini yapabildiği için Işık Elfi ismi verildi. Işık Elfleri Orman Elfleri ile birlikte çalışarak tarım yapmayı mümkün kıldı.","chars":[],"places":["Elf kıtası"],"factions":["High Elfler","Işık Elfleri","Orman Elfleri"],"cons":"Işık büyüsüyle Orman Elfleri birlikte tarımı mümkün kılar; Işık Elfleri sonraki çağlarda (Güneş Savaşları, Orc'a dönüştürülme) önemli bir ırk olur.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kanunsuz","tier":"antik","img":null},{"o":18,"date":"2748","big":"2748","num":true,"title":"Yeni Bir Umut","desc":"Bu yıldan itibaren ilkbahar ve yaz aylarında dışarı çıkılabilmeye başlandı.","chars":[],"places":["Horaghfus"],"factions":[],"cons":"İlkbahar ve yaz aylarında yüzeye çıkmak mümkün hâle gelir; yeryüzüne dönüşün ilk adımı.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kanunsuz","tier":"antik","img":null},{"o":19,"date":"2799","big":"2799","num":true,"title":"Manayutan Şehir Baskınları","desc":"Tam Horaghfuslular umutlanacakken Manayutanlar evrim geçirerek tünellere girebilmeye başladı. Karasırt-Tor'araf ve Yemin şehirlerini aniden basarak yok ettiler. Bu baskınlarda birçok asil öldü ancak Ölüm'ün taş verdiği asiller geri döndü ve böylece asil aile sayısı azalmış oldu. Şehirler yok olunca Horaghfuslular tünellere ve haydutların inleine kaçmak zorunda kaldı. Birkaç günlük katliamdan sonra Manayutanlar yüzeye geri döndü. Bu olaydan sonra Manayutanları yenmek için her ırk çalışmaya başladı.","chars":[],"places":["Karasırt","Tor'araf","Yemin"],"factions":["Manayutanlar","Horaghfus asil aileleri"],"cons":"Üç yeraltı şehri yok olur; asil aile sayısı azalır (Ölüm'ün taş verdiği asiller geri döner). Halk tünellere ve haydut inlerine dağılır; her ırk Manayutanları yenmek için çalışmaya başlar.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kanunsuz","tier":"antik","img":null},{"o":20,"date":"3000","big":"3000","num":true,"title":"KEDER YAĞIŞLARININ SONU","desc":"Kronolojik cetvel 3'de yalnızca başlık olarak yer alıyor: \"3000 KEDER YAĞIŞLARININ SONU\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Horaghfus"],"factions":[],"cons":"Bin yıllık Keder Yağışları sona erer; yüzey soğuk ama yaşanabilir hâle gelir ve yeryüzüne dönüş başlar.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":{"src":"assets/art/53_Horaghfus.webp","w":1280,"h":990,"kind":"user"}},{"o":21,"date":"3000","big":"3000","num":true,"title":"Savaşa Çağrı!","desc":"Yağışlar durdu ve yeryüzü soğuk ama yaşanabilir hale geldi. Öğle vakti gerçekleşen büyük deprem o kadar korkutucuydu ki tünellerde yaşayanlar dışarı kaçmak zorunda hissetti. Dışarı çıktıklarında havanın yaşanabilir olduğunu fark ettiklerinde Manayutanları bitirmek için savaşlara başlandı.","chars":[],"places":["Horaghfus","Yeraltı tünelleri"],"factions":["Horaghfus ırkları","Manayutanlar"],"cons":"Yeraltında yaşayan halklar yüzeye geri döner ve Manayutanları yok etmek için savaşlar başlar; bu süreç 3050'deki Manayutan–Horaghfus Savaşı'na varır.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":22,"date":"3050","big":"3050","num":true,"title":"Manayutan-Horaghfus Savaşı","desc":"Horaghfus'taki bütün taraflar/ırklar birleşmese de hepsi Manayutanlarla savaştı ve sonunda (Manayutanların) soyları tükendi.","chars":[],"places":["Horaghfus"],"factions":["Horaghfus ırkları","Manayutanlar"],"cons":"Tüm ırklar (birleşmeden de olsa) Manayutanlarla savaşır ve Manayutanların soyu tükenir.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":23,"date":"3382","big":"3382","num":true,"title":"Zaaf Naraları gecesi","desc":"Hobbitler, Güneyli krallıkların hazinelerini Singulken bölgesi civarına getirdi ve orada kendi krallıklarını kurdu (I. Hobbit Krallığı). Krallıklarının 1. yılını kutlarken Hobbit kralı Wolbodo kendisine biraz ayırdıktan sonra bütün altınları halka dağıttı. Altına boğulan Hobbitler çok geçmeden altın hastalığına yakalandı. Zaaf Naraları ismi verilen bu gecede Hobbitler birbirine girdi ve krallıkları yıkıldı. Horaghfus'a yayılan Hobbitler gittikleri bölgelerde ya soyuldu ya da altınları için öldürüldü. Hobbit ırkı hastalıktan kurtuldu ama bu milli egemenliklerine mal oldu.","chars":["Wolbodo"],"places":["Singulken"],"factions":["Hobbitler","I. Hobbit Krallığı"],"cons":"Altın hastalığına yakalanan Hobbitler birbirine girer; I. Hobbit Krallığı yıkılır. Hobbitler dağılır, soyulur ve milli egemenliklerini kaybeder.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":24,"date":"3426","big":"3426","num":true,"title":"Arowuhl şelalesinin oluşması","desc":"Ægnádr isimli bir dev, Keder Yağışlarının bıraktığı son karların erimesiyle oluşan göl ve nehirlerin taşmaya başladığını görünce toprağı elleriyle yararak taşan suya yol açtı. Ardından dev dilinde bir dua ile tanrıya ona güç vermesi için rica etti. Birkaç saniye sonra şelaleye eğildi ve \"Bin yıllar boyunca, burada hayat olduğu sürece bu şelale şeklini değiştirmesin, kimseye zarar vermesin\" dedi ve üfledi.","chars":["Ægnádr"],"places":["Arowuhl şelalesi"],"factions":["Devler"],"cons":"Dev Ægnádr'ın duasıyla oluşan şelale binlerce yıl şeklini değiştirmeyecek biçimde kutsanır; Arowuhl'un simgesi olur.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":25,"date":"3499","big":"3499","num":true,"title":"Arowuhl krallığı ve şehrinin kurulması","desc":"Kronolojik cetvel 3'de yalnızca başlık olarak yer alıyor: \"3499 Arowuhl krallığı ve şehrinin kurulması\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Arowuhl","Arrowhul"],"factions":["Arowuhl Elfleri"],"cons":"Elflerin en önemli krallıklarından Arowuhl kurulur; kampanyada Kral Revalor'un hükmettiği Arrowhul bu şehirdir.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":{"src":"assets/art/43_Arrowhul.webp","w":1280,"h":549,"kind":"user"}},{"o":26,"date":"3764","big":"3764","num":true,"title":"Cüce klanlarının birleşmesi","desc":"Kronolojik cetvel 3'de yalnızca başlık olarak yer alıyor: \"3764 Cüce klanlarının birleşmesi\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Cüce dağları"],"factions":["Cüce klanları"],"cons":"Cüce klanları birleşir; Keder Yağışları'ndan sonra cüceler yeniden güçlü bir siyasi güç olur.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":27,"date":"3764–4012","big":"3764–4012","num":true,"title":"Sakin Dönem","desc":"Kronolojik cetvel 3'de yalnızca başlık olarak yer alıyor: \"3764-4012 Sakin Dönem\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Horaghfus"],"factions":[],"cons":"Cüce klanlarının birleşmesinden Paarthonax'ın kutsamasına kadar süren sakin dönem.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":28,"date":"4012","big":"4012","num":true,"title":"Paarthonax'ın kutsaması","desc":"Paarthonax isimli Ejderha batmakta olan Güney kıtasından Kobold ormanlarına doğru uçtu. Bu devasa ve kadim ejderha ormanlara girdikten sonra bir daha görülmedi; bu olaydan sonra Kobold topraklarında bereket arttı.","chars":["Paarthonax"],"places":["Güney kıtası","Kobold ormanları"],"factions":["Koboldlar"],"cons":"Kadim ejderha Paarthonax ormanlara girip bir daha görülmez; Kobold topraklarında bereket artar.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":29,"date":"4172","big":"4172","num":true,"title":"Koboldların Cehennemi","desc":"Koboldların yaşadığı ormanların birinde büyük bir yangın çıktı. Qazzeen bu yangını insan ırkının başlattığını düşünerek insanlara saldıracağını haber verdi. Ancak yangın sadece bir doğal afetti.","chars":["Qazzeen"],"places":["Kobold ormanları"],"factions":["Koboldlar","İnsanlar"],"cons":"Doğal bir orman yangınını insanların çıkardığını sanan Qazzeen insanlara savaş ilan eder; Kobold Gazabı'na (4279) giden süreç başlar.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":30,"date":"4279","big":"4279","num":true,"title":"Kobold Gazabı","desc":"Qazzeen insan kabileleri üstüne binlerce Kobold yollayarak insanları vassalı haline getirdi. Vassal olur olmaz tüm insan kütüphanelerini yok etti ve mucitlerini öldürdü. Bu savaştan sonra insanlar teknolojide aşırı yavaşladı, hatta geriledi.","chars":["Qazzeen"],"places":["Balahnur bölgesi"],"factions":["Koboldlar","İnsan kabileleri"],"cons":"İnsanlar Koboldların vassalı olur; tüm insan kütüphaneleri yok edilir ve mucitler öldürülür. İnsanlar teknolojide aşırı yavaşlar, hatta geriler.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":31,"date":"4499","big":"4499","num":true,"title":"Qazzeen Savaşı","desc":"Kobold lideri Qazzeen Balahnur bölgesindeki insan kabilelerini yok etmeye çalıştı. 6 kabile yok ettikten sonra kendi ismini taşıyan bu savaşta bir insan reisi tarafından öldürüldü.","chars":["Qazzeen"],"places":["Balahnur bölgesi"],"factions":["Koboldlar","İnsan kabileleri"],"cons":"Kobold lideri Qazzeen bir insan reisi tarafından öldürülür; Kobold tehdidi kırılır.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":32,"date":"4635","big":"4635","num":true,"title":"Kayaçene-Lüangraftbötr savaşı","desc":"6. cüce klanı olan Kayaçene klanı kendi tanrılarını ilan edince diğer cüce klanları Kayaçene'ye savaş açtı. Kayaçene reisi Gonman, Kayaçene hariç her Kayaçene cücesi klanlarının kalesini ölene dek savundu. Ortada hiç Kayaçeneli kalmamasına rağmen Gonman'ın cesedi bulunamadı.","chars":["Gonman"],"places":["Cüce dağları"],"factions":["Kayaçene klanı","Lüangraftbötr ve diğer cüce klanları"],"cons":"Kayaçene klanı yok olur; reis Gonman'ın cesedi hiç bulunamaz.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":33,"date":"4929","big":"4929","num":true,"title":"II. Hobbit krallığının kurulması","desc":"Kronolojik cetvel 3'de yalnızca başlık olarak yer alıyor: \"4929 II. Hobbit krallığının kurulması\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["II. Hobbit Krallığı"],"factions":["Hobbitler"],"cons":"Hobbitler yeniden bir krallık kurar (5100'deki salgınla yıkılacak).","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":34,"date":"5100","big":"5100","num":true,"title":"Hobbit Salgını","desc":"II. Hobbit krallığı nereden geldiği bilinmeyen bir hastalık yüzünden 2 yıl içinde yıkıldı. Sağlıklı Hobbitler Elf kıtasına kaçtı.","chars":[],"places":["II. Hobbit Krallığı","Elf kıtası"],"factions":["Hobbitler"],"cons":"II. Hobbit Krallığı iki yıl içinde yıkılır; sağlıklı Hobbitler Elf kıtasına kaçar.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":35,"date":"5113","big":"5113","num":true,"title":"Rat'tor Garaz baskını","desc":"Cüceler Dempur'u kazarken derinlerde çalışan madencilerin ışığı aniden kesildi. Kaza sanılırken madenci cüceler karanlıktan gelen kesici saldırılarla ölmeye başladı. Madene inildiğinde hiç cüce kalmamıştı; geriye iki iz kalmıştı: pençe yaraları ve bir cüce kazmasının ucunda kalmış büyük fare kuyruğu. Hiçbir şey bulunamadı; Keder Yağışlarından dolayı derinlerde ortaya çıkmayarak devleşmiş aç bir fare sürüsü olduğuna yordular. Bir daha böyle bir saldırı olmadı.","chars":[],"places":["Dempur madeni"],"factions":["Cüceler"],"cons":"Derinlerdeki madencilerin hepsi ölür; geriye pençe yaraları ve dev fare kuyruğu kalır. Bir daha böyle bir saldırı olmaz ama olay çözülmeden kalır.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":36,"date":"5275","big":"5275","num":true,"title":"Yurtaçan Savaşı","desc":"Büyü ile geçtiği Trans sırasında Arowuhl'un yıkıldığını gören Mythanar Reykalyn, halkı için yeni topraklara gitme ihtiyacı duydu; hedef olarak Gimbatul bölgesini seçti. Orada cüceler yaşıyordu ama Elflerin geleceğini tehlikeye atmamak için savaştı. Rüneal Savaşı'nın intikamını alırcasına saldırdı. Cüceler geri çekilmedi; savaş Gimbatul'da son cüce askeri kalana kadar devam etti. Savaş bittiğinde Mythanar, cüce sivillere zarar vermeden dağlara kadar askerlerine eşlik ettirdi.","chars":["Mythanar Reykalyn"],"places":["Gimbatul","Arowuhl"],"factions":["Arowuhl Elfleri","Cüceler"],"cons":"Elfler Gimbatul'u ele geçirir; Mythanar cüce sivilleri zarar görmeden dağlara kadar götürtür. Elflerin Gimbatul'a yerleşmesinin yolu açılır.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":37,"date":"5322 ile 5275 arası, tarihsiz","big":"5322 ile 5275 arası, tarihsiz","num":false,"title":"Gimbatul şehrinin kurulması","desc":"Kronolojik cetvel 3'de yalnızca başlık olarak yer alıyor: \"(5322 ile 5275 arası, tarihsiz) Gimbatul şehrinin kurulması\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":["Mythanar Reykalyn"],"places":["Gimbatul"],"factions":["Arowuhl Elfleri"],"cons":"Elfler Gimbatul bölgesine yerleşir; bölge sonraki çağlarda pek çok savaşın (Dwarrebanih, Kabza Gurur, Akan Kazan) merkezi olur.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":true,"note":"Cetvelde tarihsiz; 5275 ile 5322 arasında (sıralama için ~5300).","era":"kurtulus","tier":"ortacag","img":null},{"o":38,"date":"5322","big":"5322","num":true,"title":"Dwarrebanih Savaşı","desc":"Mythanar Reykalyn isimli Arowuhl'un Elf kralı ile Lüangraftbötr cüce klanının reisi Magmadilli Gikhon arasında Gimbatul'da bir savaş. Gimbatul'un kurulmasını istemeyen cüceler Elflere iyi ekipmanlı ve kalabalık halde saldırdı ancak Mythanar, Elf okçuları ve savaş için yetiştirdiği anka kuşları sayesinde ezici üstünlükle kazanarak cücelerin dağlardan başka yerlere gitmesini kesmiş oldu.","chars":["Mythanar Reykalyn","Magmadilli Gikhon"],"places":["Gimbatul"],"factions":["Arowuhl Elfleri","Lüangraftbötr cüce klanı"],"cons":"Elfler ezici üstünlükle kazanır; cücelerin dağlardan başka yerlere yayılması durdurulur.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":39,"date":"5322–5707","big":"5322–5707","num":true,"title":"Sakin Dönem","desc":"Kronolojik cetvel 3'de yalnızca başlık olarak yer alıyor: \"5322-5707 Sakin Dönem\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Horaghfus"],"factions":[],"cons":"Dwarrebanih Savaşı'ndan sonra yaklaşık 385 yıl süren, kayda geçmiş büyük çatışmanın olmadığı bir dönem.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"kurtulus","tier":"ortacag","img":null},{"o":40,"date":"5707","big":"5707","num":true,"title":"Jörmunngandr'ın ölümü ve Jörmünder cüce klanının kökenleri","desc":"Kronolojik cetvel 2'de yalnızca başlık olarak yer alıyor: \"5707 Jörmunngandr'ın ölümü ve Jörmünder cüce klanının kökenleri\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":["Jörmunngandr"],"places":["Horaghfus"],"factions":["Jörmünder cüce klanı"],"cons":"Jörmunngandr ölür; Jörmünder cüce klanının kökenleri bu olaya dayanır.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":41,"date":"6089","big":"6089","num":true,"title":"Kükreyen Dağlar Onyılı","desc":"Horaghfus'ta 10 yıl boyunca bütün yanardağlar aktifleşti. Cüceler lavlarla baş etmeyi biliyordu ve diğer krallıklara da yardım etti. 3. yılda topraktan çıkan kurtçuklar arttı; 7. yılda yağışlar arttı ve Keder Yağışlarının geri döndüğü düşüncesi her ırkı korkuttu. 10. yılda yanardağların ağızlarından gökyüzüne lavlar yükseldi; lavlar Dev banyosu denizinin üstünde toplanarak ateşten bir portal yarattı. Bazı Elf teologları antik tanrılardan birinin intikam için geldiğini söyledi. Işık Elfleri portalın başında bekledi. Gökyüzü kızıldı; geceyarısı portaldan çeşitli şekil ve boyutlarda kızıl yaratıklar çıktı.","chars":[],"places":["Horaghfus","Kükreyen Dağlar","Dev banyosu denizi"],"factions":["Cüceler","Işık Elfleri","Elf teologları"],"cons":"On yıl boyunca bütün yanardağlar aktifleşir, cüceler diğer krallıklara yardım eder; 10. yılda Dev banyosu denizinin üstünde ateşten bir portal oluşur ve kızıl yaratıklar çıkar (Güneş Savaşları başlar).","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":42,"date":"6099","big":"6099","num":true,"title":"Güneş Savaşları","desc":"Kükreyen Dağlar'daki ateşten portaldan çıkan kızıl yaratıklar, ateşten ve kara büyüden etkilenmiyordu. Işık Elfleriyle uzun süre savaştılar; dalga dalga geldiler, her dalgada farklı yaratıklar ve büyüler vardı, ama Işık Elfleri hepsini savuşturdu.","chars":[],"places":["Kükreyen Dağlar","Dev banyosu denizi"],"factions":["Işık Elfleri","Kızıl yaratıklar"],"cons":"Işık Elfleri onlarca yıl kızıl yaratık dalgalarını savuşturur; savaş ancak Kutsal Elma kullanılınca biter (6172).","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":43,"date":"6172","big":"6172","num":true,"title":"Güneş Savaşlarının sonu","desc":"İnsanlar Işık Elflerine, geri getirmeleri şartıyla Kutsal Elmayı kullanmaları için sundu. Işık Elfleri aralarından bir kadını seçti; kadın Kutsal Elma ile birlikte ateşten portala girdi. Saatler sonra portal kapandı; Kutsal Elma Işık Elflerinin eline ulaştı ancak kadın geri dönemedi.","chars":["Seçilen Işık Elfi kadın"],"places":["Ateşten portal","Dev banyosu denizi"],"factions":["Işık Elfleri","İnsanlar"],"cons":"Portal kapanır ve Güneş Savaşları biter; Kutsal Elma geri döner ama onu taşıyan kadın kaybolur. Elma insanlar ile Işık Elfleri arasında bir bağ olur.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":44,"date":"6317","big":"6317","num":true,"title":"Conjuration okulunun kurulması","desc":"Kronolojik cetvel 2'de yalnızca başlık olarak yer alıyor: \"6317 Conjuration okulunun kurulması\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Elf kıtası"],"factions":["Elf Conjurer'ları"],"cons":"Conjuration okulu kurulur (6593'teki Elementhaff'adt Vakası'nın yaşandığı yer).","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":45,"date":"6593","big":"6593","num":true,"title":"Elementhaff'adt Vakası","desc":"Elf Conjurer'larının okulda yaptığı bir ayin sırasında Elementaller kontrolden çıkarak Elf kıtasına yayıldı. Elementallerden biri Elemental üretmeyi öğrendi ve sayısını arttırdı.","chars":[],"places":["Elf kıtası","Conjuration okulu"],"factions":["Elf Conjurer'ları","Elementaller"],"cons":"Okuldaki bir ayin sırasında Elementaller kontrolden çıkıp kıtaya yayılır; biri Elemental üretmeyi öğrenir. Çağrılmış Savaş'a (6600) yol açar.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":46,"date":"6600","big":"6600","num":true,"title":"Çağrılmış Savaş","desc":"Efendilerine itaat etmeyen Elementaller ile Elfler arasında büyü dolu bir savaş. Dönemin önemli bir Elf büyücüsü bu savaşta öldü.","chars":[],"places":["Elf kıtası"],"factions":["Elfler","Elementaller"],"cons":"Efendilerine itaat etmeyen Elementallerle büyü dolu bir savaş yaşanır; dönemin önemli bir elf büyücüsü ölür.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":47,"date":"6601–6836","big":"6601–6836","num":true,"title":"Sakin dönem","desc":"Kronolojik cetvel 2'de yalnızca başlık olarak yer alıyor: \"6601-6836 Sakin dönem\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Horaghfus"],"factions":[],"cons":"Çağrılmış Savaş'tan Bücürlerin Savaşı'na kadar süren sakin dönem.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":48,"date":"6836","big":"6836","num":true,"title":"Bücürlerin Savaşı","desc":"Elf kıtasında yaşayan Hobbitleri kaçıran goblinler sayılarını arttırınca Elfler Hobbitlere silah desteği sağladı. Hobbitlerle kısa bir süre savaştıktan sonra goblinler bölgeden kaçtı.","chars":[],"places":["Elf kıtası"],"factions":["Hobbitler","Goblinler","Elfler"],"cons":"Elflerin silah desteğiyle Hobbitler goblinleri bölgeden kaçırır.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":49,"date":"6837","big":"6837","num":true,"title":"III. Hobbit krallığının kurulması","desc":"Kronolojik cetvel 2'de yalnızca başlık olarak yer alıyor: \"6837 III. Hobbit krallığının kurulması\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["III. Hobbit Krallığı"],"factions":["Hobbitler"],"cons":"Hobbitler üçüncü krallıklarını kurar (7036'da Amanar tarafından yok edilecek).","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":50,"date":"7036","big":"7036","num":true,"title":"Amanar Katliamı","desc":"Hobbitler kendi krallıklarında barış içinde yaşıyordu. Ancak derinlerden gelen Amanar isimli bir deniz yaratığı ortaya çıktı ve III. Hobbit krallığını yok etti; yüzlerce Hobbit'i midesine indirdikten sonra bir daha görülmedi.","chars":[],"places":["III. Hobbit Krallığı"],"factions":["Hobbitler"],"cons":"Deniz yaratığı Amanar III. Hobbit Krallığı'nı yok eder ve yüzlerce Hobbit'i yuttuktan sonra kaybolur. (Amanar, Balahnur'un tahliye gecesinde korsanlarla geri dönecektir.)","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":51,"date":"7199","big":"7199","num":true,"title":"Kuzeyin Ejderhası'nın öldürülmesi","desc":"Skallagrim sıradan bir insan oduncuydu. Kabilesi diğer kabilelerin baskısından rahatsızdı ama gidecek yerleri yoktu. Skallagrim odunculuğu bırakıp yolculuğa çıktı: önce Gimbatul, sonra cüce dağları, ardından Elf kıtası. Bir savaşçı olarak döndü; tek başına kuzeye gidip kuzeyi barınılmaz hale getiren Ejderhayı öldürdü ve kabilesini kuzeye taşıyarak kabile reisi oldu.","chars":["Skallagrim Björnulfson"],"places":["Kuzey","Gimbatul","Cüce dağları","Elf kıtası"],"factions":["Kuzey kabileleri"],"cons":"Kuzey yeniden yaşanabilir olur; Skallagrim kabilesini kuzeye taşıyıp reis olur.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":52,"date":"7200","big":"7200","num":true,"title":"Skallagrim Björnulfson'un reis olması","desc":"Kronolojik cetvel 2'de yalnızca başlık olarak yer alıyor: \"7200 Skallagrim Björnulfson'un reis olması\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":["Skallagrim Björnulfson"],"places":["Kuzey"],"factions":["Kuzey kabileleri"],"cons":"Ejderhayı öldüren Skallagrim kabilesinin reisi olur.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":53,"date":"7255","big":"7255","num":true,"title":"Skallagrim Björnulfson'un cenazesi","desc":"Kronolojik cetvel 2'de yalnızca başlık olarak yer alıyor: \"7255 Skallagrim Björnulfson'un cenazesi, Kuzeyli insanların kökeni\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":["Skallagrim Björnulfson"],"places":["Kuzey"],"factions":["Kuzeyli insanlar"],"cons":"Kuzeyli insanların kökeni bu kahramana dayanır.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":54,"date":"7256–7489","big":"7256–7489","num":true,"title":"Sakin dönem","desc":"Kronolojik cetvel 2'de yalnızca başlık olarak yer alıyor: \"7256-7489 Sakin dönem\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Horaghfus"],"factions":[],"cons":"Skallagrim'in cenazesinden Delik Varil Kıtlığı'na kadar süren sakin dönem.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":55,"date":"7489","big":"7489","num":true,"title":"Delik Varil Kıtlığı","desc":"Bir Hobbit'in bulduğu lamba cinine dilediği dilek yüzünden Horaghfus'ta yıllarca kıtlık yaşandı. Arowuhl'lu Elfler kıtlık lanetini kaldırmayı başardı.","chars":[],"places":["Horaghfus","Arowuhl"],"factions":["Hobbitler","Arowuhl Elfleri"],"cons":"Bir Hobbit'in lamba cinine dilediği dilek yüzünden yıllarca kıtlık yaşanır; Arowuhl Elfleri laneti kaldırır.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":56,"date":"7671","big":"7671","num":true,"title":"Kabza Gurur Savaşı","desc":"Atalarını onurlandırmak için düzenlenen cüce festivalindeki kazı kazma yarışında Bronzçınar klanının sırasını Strömbah klanı çalınca iki klan arasında kavga çıktı. Kavga büyüyerek savaşa dönüştü; 5 cüce klanı yıllarca savaştı. Son savaşta Gimbatullu elflerin cüce sınırlarının ötesine geçtiğini öğrenince hepsi birden Elflere saldırdı. Gimbatullu Elfler durumun bir yanlış anlaşılma olduğunu söyleyip özür diledi; gerçekten de saldırma niyetleri yoktu. Bu olay üzerine cüce klanları savaşı hiçbir tarafın kazanmadığını kabul ederek barıştı.","chars":[],"places":["Cüce dağları","Gimbatul"],"factions":["Bronzçınar klanı","Strömbah klanı","Gimbatullu Elfler"],"cons":"Beş cüce klanı yıllarca savaşır; sonunda Elflere saldırırlar ama bunun bir yanlış anlaşılma olduğu anlaşılınca hiçbir tarafın kazanmadığını kabul edip barışırlar.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":57,"date":"7815","big":"7815","num":true,"title":"I. Khotekx Savaşı","desc":"İnsanlar ile Koboldlar arasındaki Khotekx savaşlarının ilki. Bu savaşlarda Koboldlar çok fazla kayıp verdi; Kobold köy ve şehirleri yıkıldı.","chars":[],"places":["Kobold toprakları","Balahnur bölgesi"],"factions":["İnsanlar","Koboldlar"],"cons":"Koboldlar ağır kayıp verir; ikinci savaşa ve Kobold başkentinin düşüşüne zemin hazırlanır.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":58,"date":"7818","big":"7818","num":true,"title":"II. Khotekx Savaşı","desc":"İnsanlar ile Koboldlar arasındaki ikinci Khotekx savaşı. Daha fazla kayba dayanamayan Koboldlar teslim oldu ve Kobold başkentinin yerine Balahnur kuruldu.","chars":[],"places":["Kobold başkenti","Balahnur"],"factions":["İnsanlar","Koboldlar"],"cons":"Koboldlar teslim olur; Kobold başkentinin yerine Balahnur kurulur (7822).","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":59,"date":"7822","big":"7822","num":true,"title":"Balahnur krallığı ve şehrinin kurulması","desc":"Kronolojik cetvel 2'de yalnızca başlık olarak yer alıyor: \"7822 Balahnur krallığı ve şehrinin kurulması, Prens Askar'ın soyunun kökenleri\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":["Prens Askar (soyu)"],"places":["Balahnur"],"factions":["Balahnur Krallığı","Koboldlar"],"cons":"Kobold başkentinin yerine Balahnur kurulur; Prens Askar'ın soyunun kökenleri bu döneme dayanır. Balahnur kampanyanın ana şehri olacaktır.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":{"src":"assets/art/46_Balahnur.webp","w":1280,"h":543,"kind":"user"}},{"o":60,"date":"7954","big":"7954","num":true,"title":"İnsan topluluklarının kuzeye göçü","desc":"Kronolojik cetvel 2'de yalnızca başlık olarak yer alıyor: \"7954 İnsan topluluklarının kuzeye göçü\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Kuzey"],"factions":["İnsan toplulukları"],"cons":"İnsan toplulukları kuzeye göç eder; kuzey krallıklarının ve Blavinken'in kurulmasına zemin hazırlanır.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":61,"date":"7960–8102","big":"7960–8102","num":true,"title":"Sakin dönem","desc":"Kronolojik cetvel 2'de yalnızca başlık olarak yer alıyor: \"7960-8102 Sakin dönem\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Horaghfus"],"factions":[],"cons":"İnsanların kuzeye göçünden Blavinken'in kuruluşuna kadar süren sakin dönem.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"gunes","tier":"ortacag","img":null},{"o":62,"date":"8102","big":"8102","num":true,"title":"Blavinken şehrinin ve krallığının kurulması","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"8102 Blavinken Şehrinin ve krallığının kurulması, Narnold soyunun kökenleri\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":["Narnold (soyu)"],"places":["Blavinken"],"factions":["Blavinken Krallığı","Narnold soyu"],"cons":"Blavinken kurulur; İmparatorluğu kuracak Narnold soyunun kökenleri buraya dayanır. (Kampanyada River'ın ailesinin zamanda donmuş evi Blavinken ormanlarında.)","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":{"src":"assets/art/47_Blavinken.webp","w":1280,"h":543,"kind":"user"}},{"o":63,"date":"8102–9072","big":"8102–9072","num":true,"title":"Aidiyet Savaşları","desc":"Krallık kurmak için uygun fırsatı bekleyen bazı kişiler başka insanları etrafında toplayarak Horaghfus insanlarının çoğunlukla yaşadığı yerlerde kendi krallıklarını ilan etmeye başladı. Yüzyıllar boyunca insanlar birbiriyle savaşarak kral bildikleri insanlar için öldü. Bu savaşlarda sağ kalan krallar kendi krallıklarını kurmayı başardı ve insanlar kendi aralarında ayrışmış oldu.","chars":[],"places":["Horaghfus"],"factions":["İnsan krallıkları"],"cons":"Yüzyıllarca süren savaşlardan sağ kalan krallar kendi krallıklarını kurar; insanlar kendi aralarında bölünür.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":64,"date":"8559","big":"8559","num":true,"title":"Kuzeyli krallıkların kurulması","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"8559 Kuzeyli krallıkların kurulması\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Kuzey"],"factions":["Kuzeyli krallıklar"],"cons":"Kuzeyli krallıklar kurulur.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":65,"date":"8730","big":"8730","num":true,"title":"Yakutlar'ın kurulması","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"8730 Yakutlar'ın kurulması\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Yakutlar"],"factions":["Yakutlar"],"cons":"Gimbatul'un batısında Yakutlar kurulur.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":66,"date":"8900","big":"8900","num":true,"title":"Kuzey İttifakı'nın kurulması","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"8900 Kuzey İttifakı'nın kurulması\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Kuzey"],"factions":["Kuzey İttifakı"],"cons":"Kuzeyli insan krallıkları müttefik olur (beş yıl sonra cücelere savaş açacaklar).","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":67,"date":"8905","big":"8905","num":true,"title":"Kül Katuz Savaşı","desc":"Kuzeydeki insan krallıkları müttefik olarak Gimbatul'un kuzeyindeki dağları ele geçirmek için cücelere savaş açtı. Yükseklerde gerçekleşen savaş 1 yıl bile sürmedi. Cüceler kuzeyli insanları dağlardan Vipreflumen'e kadar kovaladı ve kuzeyli krallıklar cüce klanlarının üstünlüğünü kabul etti.","chars":[],"places":["Gimbatul'un kuzeyindeki dağlar","Vipreflumen"],"factions":["Kuzey İttifakı","Cüce klanları"],"cons":"Cüceler kuzeyli insanları dağlardan Vipreflumen'e kadar kovalar; kuzeyli krallıklar cüce klanlarının üstünlüğünü kabul eder.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":68,"date":"8905","big":"8905","num":true,"title":"Kuzey İttifakı'nın bozulması","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"8905 Kuzey İttifakı'nın bozulması\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Kuzey"],"factions":["Kuzey İttifakı"],"cons":"Kül Katuz yenilgisinden sonra Kuzey İttifakı bozulur.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":69,"date":"9072","big":"9072","num":true,"title":"Suskun Diyar Krallığı'nın kurulması","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"9072 Suskun Diyar Krallığı'nın kurulması\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Suskun Diyar"],"factions":["Suskun Diyar Krallığı"],"cons":"Blavinken'in batısındaki yarımadada Suskun Diyar Krallığı kurulur (9440'ta Balahnur'a yenilecek).","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":70,"date":"9240","big":"9240","num":true,"title":"Madenci Bayramı","desc":"9240 yılının ilkbaharında Horaghfus'ta her ırktaki madenciler büyük altın ve değerli taş yatakları keşfetti. Cüce madenciler başta olmak üzere birçok madenci zenginleşti; kimileri güçlendi, kimilerine ise sadece bela getirdi.","chars":[],"places":["Horaghfus"],"factions":["Cüce madenciler"],"cons":"Büyük altın ve değerli taş yatakları keşfedilir; birçok madenci zenginleşir, kimileri güçlenir, kimilerine bela gelir.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":71,"date":"9244","big":"9244","num":true,"title":"Kasvetli Nefes Olayı","desc":"Keder Yağışlarını sonlandıran depremden beri gerçekleşen en büyük Horaghfus depremi. Evleri ve sarayları yıkarak neredeyse her krallığı zor duruma soktu. Güneyin yıkılmış krallıklarının zaten batmakta olan antik şehirleri de bu deprem sonucunda sular altında kaldı. Depremden sonra yer altından çıkan sıcak buharlardan dolayı \"Kasvetli Nefes Olayı\" adını aldı.","chars":[],"places":["Horaghfus","Güney Toprakları"],"factions":["Tüm krallıklar"],"cons":"Keder Yağışları'nı bitiren depremden beri en büyük deprem; neredeyse her krallık zor durumda kalır, Güney'in antik şehirleri sular altında kalır.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":72,"date":"9245–9438","big":"9245–9438","num":true,"title":"Sakin Dönem (9245–9438)","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"9438-9245 Sakin Dönem\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Horaghfus"],"factions":[],"cons":"Kasvetli Nefes Olayı'ndan Prens Askar'ın savaşlarına kadar süren sakin dönem.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":true,"note":"Cetvelde '9438-9245' yazıyor (ters sıra); dönem 9245–9438 olarak okundu.","era":"imparatorluk","tier":"yagli","img":null},{"o":73,"date":"9411","big":"9411","num":true,"title":"Ivar Mannavegr'in ilk yağmaları","desc":"Kuzeyli bir denizci olan Ivar, kendi filosunu toplayarak okyanusa kıyısı olan her devlete yağma saldırıları yaparak yakalanana dek korku saldı.","chars":["Ivar Mannavegr"],"places":["Okyanus kıyıları"],"factions":["Kuzeyli denizciler"],"cons":"Ivar kendi filosuyla okyanusa kıyısı olan her devleti yağmalar ve yakalanana dek korku salar.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":74,"date":"9432","big":"9432","num":true,"title":"Yuvarlak Masa Yolu'nun kurulması","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"9432 Yuvarlak Masa Yolu'nun kurulması\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Yuvarlak Masa Yolu"],"factions":[],"cons":"Cetvelde yalnızca başlık olarak geçer: Yuvarlak Masa Yolu kurulur.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":75,"date":"9436","big":"9436","num":true,"title":"Ivar Mannavegr'in ortadan kaybolması","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"9436 Ivar Mannavegr'in ortadan kaybolması\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":["Ivar Mannavegr"],"places":["Okyanus kıyıları"],"factions":["Kuzeyli denizciler"],"cons":"Korsan Ivar Mannavegr ortadan kaybolur.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":76,"date":"9438","big":"9438","num":true,"title":"Pullar Savaşı","desc":"Balahnur Krallığındaki köle Koboldlar isyan ederek şehrin etrafındaki köylere saldırmaya başladı. Balahnur'un genç prensi Askar, Koboldların Qibok Pençegöz isimli liderleri ile savaşarak isyanı bastırdı. Koboldlar köle olarak kalmaya devam etti.","chars":["Prens Askar","Qibok Pençegöz"],"places":["Balahnur"],"factions":["Balahnur Krallığı","Köle Koboldlar"],"cons":"Genç Prens Askar Kobold isyanını bastırır; Koboldlar köle olarak kalmaya devam eder.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":77,"date":"9439","big":"9439","num":true,"title":"Yakut Beyi Savaşı","desc":"Gimbatul'un batısında olan Yakutlar ile Balahnur arasındaki savaş; amaç stratejik bölgeye sahip Yakutları ele geçirmekti. Prens Askar muzaffer ayrıldı. (açıklama çizgisi 9439 civarına bağlı; okuma kesin değil)","chars":["Prens Askar"],"places":["Yakutlar","Gimbatul"],"factions":["Yakutlar","Balahnur"],"cons":"Stratejik Yakut bölgesi ele geçirilir; Prens Askar muzaffer ayrılır.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":true,"note":"Açıklama çizgisi 9439 civarına bağlı; okuma kesin değil.","era":"imparatorluk","tier":"yagli","img":null},{"o":78,"date":"9440","big":"9440","num":true,"title":"Suskun Diyar Savaşı","desc":"Blavinken'in batısındaki yarımadanın üstünde kurulmuş bir şehir olan Suskun Diyar ile Balahnur arasında kısa bir savaş; Prens Askar az kayıp vererek kazandı.","chars":["Prens Askar"],"places":["Suskun Diyar","Blavinken"],"factions":["Suskun Diyar","Balahnur"],"cons":"Prens Askar az kayıpla kazanır.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":79,"date":"9442","big":"9442","num":true,"title":"Donmuş Kan Savaşı","desc":"Balahnur'un kuzeyinde bulunan Halldor krallığı ile Balahnur arasında kanlı bir savaş. Prens Askar bu savaş ile iyi bir ün kazandı ancak iki tarafın da döktüğü kan karların rengini kızıla çevirdi; bu yüzden bu savaşa Donmuş Kan Savaşı denildi.","chars":["Prens Askar"],"places":["Halldor krallığı","Balahnur"],"factions":["Halldor krallığı","Balahnur"],"cons":"Prens Askar ün kazanır; iki tarafın döktüğü kan karları kızıla boyar.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":80,"date":"9443","big":"9443","num":true,"title":"Bereket Nehri Savaşı","desc":"Blavinken'in kuzeyinde Bereket Nehri adlı ikiz nehrin üstüne kurulmuş olan Olik Tarikatı krallığıyla Prens Askar arasında dini sebeplerden ötürü gerçekleşen savaş; Prens Askar kazandı.","chars":["Prens Askar"],"places":["Bereket Nehri","Blavinken"],"factions":["Olik Tarikatı krallığı","Balahnur"],"cons":"Dinî sebeplerle çıkan savaşı Prens Askar kazanır.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":81,"date":"9444","big":"9444","num":true,"title":"Vipreflumen Savaşı","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"9444 Vipreflumen Savaşı\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Vipreflumen"],"factions":["Balahnur"],"cons":"Cetvelde yalnızca başlık olarak geçer; Prens Askar dönemi savaşlarından biri.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":82,"date":"9447–9450","big":"9447–9450","num":true,"title":"Saklı Prens Savaşı","desc":"Kuzeyli krallıklar ile Balahnur arasında zorlu savaşlar yaşandı. Savaşın ortasında Prens Askar'ın 3 yıldır ölü olduğu ve onun yerine karısının savaşı yönettiği ortaya çıktı. Prense aşırı bağlı olan halk, prensin katilinin karısı olduğunu düşünerek karısını linç ederek öldürdü. Savaşın komutasını Kutsal Elmanın taşıyıcısı olan Narnold aldı ve savaşı kazanarak insan krallıklarını birleştirip İmparatorluğu kurdu.","chars":["Prens Askar","Narnold"],"places":["Balahnur","Kuzey krallıkları"],"factions":["Balahnur","Kuzeyli krallıklar"],"cons":"Prens Askar'ın 3 yıldır ölü olduğu ortaya çıkar; halk karısını katil sanıp linç eder. Kutsal Elma taşıyıcısı Narnold komutayı alır, savaşı kazanır ve İmparatorluğu kurar.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":83,"date":"9450","big":"9450","num":true,"title":"İmparatorluğun kuruluşu","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"9450 İmparatorluğun kuruluşu\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":["Narnold"],"places":["Balahnur","Blavinken"],"factions":["İmparatorluk"],"cons":"İnsan krallıkları birleşerek İmparatorluğu kurar; kampanyanın İmparatoriçesi bu hanedandan gelir.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":{"src":"assets/art/46_Balahnur.webp","w":1280,"h":543,"kind":"user"}},{"o":84,"date":"9455","big":"9455","num":true,"title":"İnsan mülteci krizi","desc":"İnsanlar arasındaki bitmek bilmeyen savaşlardan usanan veya yeni düzeni istemeyen insanlar diğer krallıklara kaçmaya başladı. Boraldmir soyu memnuniyetle insanları ülkelerine kabul etti. İnsanlar Elf kültürüne göre hareket etmedi; Elf topraklarında suç, açlık ve hastalıklar artarak Elflere zarar vermeye başladı. Reneagor Sin Boraldmir, babasının fikrini ısrarla değiştirmeye çalıştı ancak fikri değişmedi. Reneagor, büyük ablası ile birlikte tahtı ele geçirmeye çalıştı ancak başarısız oldu. Bunun sonucunda Reneagor 150 yaşında saraydan sürüldü ve tahta geçene dek Elf kütüphanelerinden çıkmadı.","chars":["Reneagor Sin Boraldmir"],"places":["Elf kıtası"],"factions":["Boraldmir soyu","İnsan mülteciler"],"cons":"Elf topraklarında suç, açlık ve hastalık artar. Reneagor tahtı ele geçirmeye çalışıp başarısız olur ve 150 yaşında saraydan sürülür. (Kampanyadaki Mital Alari'de insanların elf şehrini 'Balahnur'a çevirmesi' bu olayın yankısı.)","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":85,"date":"9455–9598","big":"9455–9598","num":true,"title":"Sakin dönem","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"9455-9598 Sakin dönem\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Horaghfus"],"factions":[],"cons":"İnsan mülteci krizinden Elf Savaşları'na kadar süren sakin dönem.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":86,"date":"9548","big":"9548","num":true,"title":"Boraldmir'in tahta geçişi","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"9548 Boraldmir'in tahta geçişi\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":["Boraldmir"],"places":["Elf kıtası"],"factions":["Boraldmir soyu"],"cons":"Boraldmir tahta geçer.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":87,"date":"9577","big":"9577","num":true,"title":"Akan Kazan Savaşı","desc":"İnsanlar (İmparatorluk), Elfler (Thranduil) ve Cüceler (Bronzçınar) Gimbatul için savaştı. Savaşı Thranduil kazandı.","chars":["Thranduil"],"places":["Gimbatul"],"factions":["İmparatorluk","Thranduil'in Elfleri","Bronzçınar klanı"],"cons":"Gimbatul için savaşı Thranduil kazanır; bu savaş yüzünden Boraldmir Güneyli Elflere saldırdığında kimse yardıma gitmez.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":88,"date":"9598","big":"9598","num":true,"title":"Elf Savaşları (başlangıç)","desc":"Elf krallıkları Boraldmir'in müttefikleri ve diğerleri olarak iki tarafta toplandı. Başta insanların Elflerin kıtasından sürülmesi gerektiği gibi sebepler olmak üzere çeşitli sebeplerle yüzyıllarca savaştılar. Bu savaşlar ve entrikalarla birlikte Boraldmir kıtanın tamamını kontrolü altına aldı.","chars":["Boraldmir"],"places":["Elf kıtası"],"factions":["Boraldmir'in müttefikleri","Diğer elf krallıkları","İnsanlar"],"cons":"Elf krallıkları iki tarafa bölünür; insanların kıtadan sürülmesi gibi sebeplerle yüzyıllarca savaşırlar. Savaşlar ve entrikalarla Boraldmir kıtanın tamamını kontrol altına alır.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":89,"date":"9734","big":"9734","num":true,"title":"Elf Savaşları'nın sonu","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"9734 Elf Savaşları'nın sonu\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":["Boraldmir"],"places":["Elf kıtası"],"factions":["Elf krallıkları"],"cons":"Yüzyıllar süren Elf Savaşları biter; Boraldmir kıtanın tamamının kontrolünü ele geçirmiştir.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":90,"date":"9735","big":"9735","num":true,"title":"Işık Elfleri'nin Orc'a dönüştürülmesi","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"9735 Işık Elfleri'nin Orc'a dönüştürülmesi\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Elf kıtası"],"factions":["Işık Elfleri","Orclar"],"cons":"Işık Elfleri Orc'a dönüştürülür.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":91,"date":"9737","big":"9737","num":true,"title":"Büyü Kusulması","desc":"Bir sabah, Horaghfuslu büyücüler güçlerinin tükenmediğini fark etti. Artık büyü kullanmak için dinlenmelerine gerek yoktu.","chars":[],"places":["Horaghfus"],"factions":["Büyücüler"],"cons":"Büyücüler güçlerinin artık tükenmediğini fark eder; büyü kullanmak için dinlenmek gerekmez. Büyünün yıkıcı gücü artar (Nasihir Akademisi'nin kurulmasına giden süreç).","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":92,"date":"9738–9761","big":"9738–9761","num":true,"title":"Horaghfus Savaşı","desc":"Elf kıtasının hakimi Boraldmir hızlı bir saldırı ile önce Singulken'i sonra da Arowuhl'u ele geçirerek Horaghfustaki Elflerin tek kralı haline geldi. Akan Kazan Savaşı'ndan dolayı bu savaşta Güneyli Elflere kimse yardıma gitmedi ve fethedilmeleri umursanmadı. Ardından hiç vakit kaybetmeden cücelere saldırdı. Savaşın ortasında İmparatorluk, Elflerin aşırı büyümesinden rahatsız olup Boraldmir'e savaş açtı. Boraldmir hem insan hem de cüce ordularını unutulmayacak bir vahşetle bozgunlara uğrattı. Bazı Elfler Boraldmir'in şiddetine karşı çıktı ve karşı tarafa katıldı ancak bir işe yaramadı. Boraldmir ölümsüz olarak görülüyordu. Bu yüzden Horaghfusta umut ışığı sönmek üzereyken üç ırk birleşerek bir hançer dövdü. Bu hançer Boraldmir'in ruhunu hapsedecekti. Hançeri döven ve rünleyen usta bir cüceydi, kabzasını Orman Efleri hazırlamıştı, kesici kısmı ise insanlar tasarlamıştı.","chars":["Boraldmir"],"places":["Singulken","Arowuhl","Elf kıtası","Cüce dağları"],"factions":["Boraldmir","İmparatorluk","Cüceler","Güneyli Elfler"],"cons":"Boraldmir Singulken ve Arowuhl'u ele geçirip Horaghfus'taki elflerin tek kralı olur; insan ve cüce ordularını vahşetle bozguna uğratır. Umut tükenirken üç ırk birleşip onun ruhunu hapsedecek hançeri döver.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":93,"date":"9761","big":"9761","num":true,"title":"Revalor'un doğumu","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"9761 Revalor'un doğumu (sarı renkle vurgulanmış)\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":["Revalor Olawarin"],"places":["Elf kıtası"],"factions":["Elfler"],"cons":"Kampanyanın Elf Kralı Revalor doğar (cetvelde sarıyla vurgulanmış); Büyük Savaş sırasında ~140 yaşında olacaktır.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":{"src":"assets/art/45_Arrowhul_TahtOdasi.webp","w":1280,"h":720,"kind":"user"}},{"o":94,"date":"tarihsiz, 9763 ile 9761 arası","big":"tarihsiz, 9763 ile 9761 arası","num":false,"title":"Boraldmir'in bozgunu","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"(tarihsiz, 9763 ile 9761 arası) Boraldmir'in bozgunu\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":["Boraldmir"],"places":["Horaghfus"],"factions":["Üç ırk (insan, elf, cüce)","Boraldmir"],"cons":"Üç ırkın dövdüğü hançerle Boraldmir'in ruhu hapsedilir ve bozguna uğratılır; 9902'deki dönüşüne kadar ortadan kalkar.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":true,"note":"Cetvelde tarihsiz; 9761 ile 9763 arasında.","era":"imparatorluk","tier":"yagli","img":null},{"o":95,"date":"9763","big":"9763","num":true,"title":"Nasihir Akademisi'nin kurulması","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"9763 Nasihir Akademisi'nin kurulması\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Nasihir Akademisi"],"factions":["Horaghfuslu krallıklar","Büyücüler"],"cons":"Büyülerin yıkıcı gücü fark edildikten sonra krallıklar büyücüleriyle Nasihir Akademisi'ni kurar.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":96,"date":"9778","big":"9778","num":true,"title":"Akademinin çöküşü","desc":"Büyülerin yıkıcı gücü fark edildikten sonra Horaghfuslu krallıklar büyücüleriyle bu akademiyi kurdu. Ancak bitmek bilmeyen saldırılar sonucunda büyücüler sinaya çekildi ve akademi dağıldı.","chars":[],"places":["Nasihir Akademisi"],"factions":["Horaghfuslu krallıklar","Büyücüler"],"cons":"Bitmek bilmeyen saldırılar sonucunda büyücüler sinaya çekilir ve akademi dağılır. (Kampanyada Nasihir yeniden faaliyette: Baş Büyücü Nebukadnezar ve kara buz.)","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":97,"date":"9778–9901","big":"9778–9901","num":true,"title":"Sakin dönem","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"9778-9901 Sakin dönem\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Horaghfus"],"factions":[],"cons":"Akademinin çöküşünden Boraldmir'in dönüşüne kadar yaklaşık 120 yıl süren sakin dönem.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"imparatorluk","tier":"yagli","img":null},{"o":98,"date":"Oyun öncesi — Aldric 8 yaşında","big":"Oyun öncesi","num":false,"title":"Arkwright ailesinin katledilmesi","desc":"Soylu Arkwright ailesinin evine özel maskeli birden fazla saldırgan baskın yapar; Aldric'in annesi ve babası öldürülür. Sekiz yaşındaki Aldric dolabın içinde saklanırken katilin elindeki koyu metal, 'T' harfli yüzüğü görür. TimeSkip1 geri dönüşlerine göre baba, ailenin savaşta prense hizmet ettiğini ve görev için Narnia'ya gidebileceğini anlatmıştı. Story.pdf'teki '3 artificier' anlatımı bu çok kişili baskınla uyumlu. (Session 5 notundaki '18 yaşında katledilen ailesi' ifadesi 18 yaşındaki intikamı kastediyor; aile katledildiğinde Aldric 8 yaşındaydı.)","chars":["Aldric Vorn Arkwright","Arkwright ailesi"],"places":["Balahnur","Arkwright evi"],"factions":["Arkwright ailesi","Barışbozanlar (Peacebreakers)"],"cons":"Aldric yetim kalır; hayatı intikam ve kontrol ihtiyacı üzerine kurulur. 'T' harfli yüzük ileride Barışbozan yüzüğü olarak hayatına girer.","major":true,"src":["The Arkwright Chronicles","Echoes of the Past","TimeSkip 1"],"unc":true,"note":"Oyun içi yıl yazılı değil; Aldric'in yaşına göre kampanyadan ~20 yıl önce (çıkarım). Kampanya Büyük Savaş'tan (9902 sonrası) hemen sonra başladığına göre Aldric'in geçmişi büyük olasılıkla 9902'den önceye düşer (sıralama çıkarımı).","era":"koken","tier":"klasik","img":{"src":"assets/art/37_Thanatos.webp","w":636,"h":618,"kind":"user"}},{"o":99,"date":"Oyun öncesi — Aldric 18 yaşında","big":"Oyun öncesi","num":false,"title":"İlk cinayet ve Barışbozan yüzüğü","desc":"On yıl sonra, Balahnur'un 39. Cadde'sinde, demircinin arka sokağında Aldric yüzüğü tanıdığı kara tenli, uzun kulaklı adamı (bir kara elf) hançerle öldürür. Ceset toza dönüşür. Aldric yüzüğü parmağına takar, adamın tinker's tools'larını alır ve babasının eski atölyesine gider. Yüzük, ailesinin katili olan bir Barışbozan'a (Peacebreaker) aitti. Story.pdf'e göre bu Barışbozan maskeli bir artificier'dı ve yüzük her yüzü gösterebilen kadim bir elf yüzüğüydü. Vindicator kask sisteminin adı da bu yüzden 'Calculative Peacebreaker System'.","chars":["Aldric Vorn Arkwright","Barışbozan (kara elf)"],"places":["Balahnur","39. Cadde","Arkwright atölyesi"],"factions":["Barışbozanlar (Peacebreakers)"],"cons":"Aldric intikamını alır ama yüzüğü takarak katilin anısını yıllarca taşır. Yüzük sonradan Thanatos/Limbic dışında üçüncü bir sese (Tamrill Ar Aserihn) kapı açar. Aldric yüzüğü ancak River için yakar.","major":true,"src":["The Arkwright Chronicles","Aldric’in hikâyesi","Vindicator kayıtları"],"unc":true,"note":"Oyun içi yıl yazılı değil (Aldric 18 yaşında). Kampanya Büyük Savaş'tan (9902 sonrası) hemen sonra başladığına göre Aldric'in geçmişi büyük olasılıkla 9902'den önceye düşer (sıralama çıkarımı).","era":"koken","tier":"klasik","img":{"src":"assets/art/06_Ark_Armatech_Old_Workshop.webp","w":1024,"h":1024,"kind":"user"}},{"o":100,"date":"Oyun öncesi — Aldric 28 yaşında","big":"Oyun öncesi","num":false,"title":"Ark Armatech'in kuruluşu","desc":"Aldric, Balahnur'un Kuzey Sanayi Bölgesi'ndeki eski bir dökümhane atölyesinde Ark Armatech'i kurar. Story.pdf'teki çekirdek kurguda Aldric 'Büyü varsa bozulur. Makineler varsa gelişir' diyen, halkın sevdiği ama kimsenin gerçekten tanımadığı vizyoner bir mühendis olarak çiziliyor. Şirket zamanla İmparatorluğun en önemli askerî üreticilerinden biri olur.","chars":["Aldric Vorn Arkwright"],"places":["Balahnur","Kuzey Sanayi Bölgesi"],"factions":["Ark Armatech"],"cons":"Ark Armatech kurulur; Aerofall, Vindicator, uçan gemiler ve İmparatorluk sözleşmeleriyle kampanyanın merkezî güçlerinden biri olur, Balahnur düşerken de 'son kale' olacaktır.","major":true,"src":["Aldric’in hikâyesi"],"unc":true,"note":"Oyun içi yıl yazılı değil. Kampanya Büyük Savaş'tan (9902 sonrası) hemen sonra başladığına göre Aldric'in geçmişi büyük olasılıkla 9902'den önceye düşer (sıralama çıkarımı).","era":"koken","tier":"klasik","img":null},{"o":101,"date":"9902","big":"9902","num":true,"title":"Boraldmir'in dönüşü","desc":"Hapsedilmiş elf hükümdarı Boraldmir 9902'de geri döner (cetvel 1). Bu dönüş Büyük Savaş'ı başlatır: Revalor Olawarin insan, elf ve cüce ırklarını ona karşı birleştirecektir. (Bu olay hem §A cetvel listesinde hem §B #1'de geçer; tek olay olarak verildi.)","chars":["Boraldmir"],"places":["Elf kıtası","Horaghfus"],"factions":["Boraldmir'in müttefikleri"],"cons":"Hapsedilmiş Boraldmir geri döner; Revalor üç ırkı yeniden birleştirip ona karşı Büyük Savaş'ı başlatır. Cetvellerdeki evren kronolojisi bu olayla biter.","major":true,"src":["Horaghfus Kronolojik Cetveli"],"unc":false,"note":null,"era":"donus","tier":"klasik","img":null},{"o":102,"date":"9903","big":"9903","num":true,"title":"Günümüz (9903)","desc":"Kronolojik cetvel 1'de yalnızca başlık olarak yer alıyor: \"9903 Günümüz\". Cetvelde bu olay için ayrıntılı açıklama yazılı değil.","chars":[],"places":["Horaghfus"],"factions":[],"cons":"Cetvel 1'in en üst etiketi; evren kronolojisinin 'şimdi' işareti.","major":false,"src":["Horaghfus Kronolojik Cetveli"],"unc":true,"note":"'9903 Günümüz' etiketinin Büyük Savaş'tan önceki mi sonraki mi 'günümüz' olduğu belgelerde açık değil.","era":"donus","tier":"klasik","img":null},{"o":103,"date":"9902 sonrası","big":"9902 sonrası","num":false,"title":"Büyük Savaş: Revalor üç ırkı birleştirir","desc":"Boraldmir'in dönüşü üzerine Revalor Olawarin insan, elf ve cüce ırklarını Boraldmir'e karşı birleştirir, Büyük Savaş'ı kazanır ve Elflerin Kralı olur. 9761'de doğan Revalor bu sırada yaklaşık 140 yaşındadır (hesap). Bu, önceki Boraldmir savaşında (9738–61) üç ırkın birleşip Boraldmir'in ruhunu hapsedecek hançeri dövmesinin tarihsel yankısıdır. Kampanyada geçen 'Üçlü İttifak' (Revalor yardımı onun adına gönderir; cüceler de 'Üçlü İttifak adına' gelir) büyük olasılıkla bu üç ırk ittifakıdır. Savaşın seyri, Boraldmir'in akıbeti ve Revalor'un taç giyme tarihi dosyalarda yazılı değil.","chars":["Revalor Olawarin","Boraldmir"],"places":["Arrowhul","Horaghfus"],"factions":["Üçlü İttifak","İnsanlar","Elfler","Cüceler","Boraldmir"],"cons":"Boraldmir yenilir; Revalor Arrowhul'da Elf Kralı olur. İnsan imparatorluğunda 40 günlük zafer festivali düzenlenir. Üçlü İttifak kampanya boyunca Balahnur'a yardım eden güç olur.","major":true,"src":["FRP Notları","Kısa Süren Bir Zafer"],"unc":true,"note":"Savaşın kesin yılı ve süresi yazılı değil.","era":"donus","tier":"klasik","img":{"src":"assets/art/44_Arrowhul_SarayGirisi.webp","w":1280,"h":720,"kind":"user"}},{"o":104,"date":"Büyük Savaş'ın hemen ardından","big":"Büyük Savaş'ın hemen ardından","num":false,"title":"Büyük Savaş sonrası yeni dönem başlar","desc":"Büyük Savaş'ın hemen ardından Balahnur merkezli yeni bir dönem açılır; Aldric Vorn Arkwright ve çevresinin olayları bu sırada başlar. Revalor Olawarin artık Arrowhul'da Elf Kralı'dır. 'Ashes Before The South' olarak anılan ilk dönem bu sırada açılır.","chars":["Aldric Vorn Arkwright","Revalor Olawarin"],"places":["Balahnur","Arrowhul"],"factions":["Ark Armatech","İmparatorluk"],"cons":"Kampanya başlar; Aldric ve The Last Bad Decision ekibinin hikâyesi bu noktadan itibaren anlatılır.","major":false,"src":["TimeSkip 1"],"unc":false,"note":null,"era":"donus","tier":"klasik","img":null},{"o":105,"date":"Cilt I — Session 4–5","big":"Cilt I","num":false,"title":"Chavel Yarışları","desc":"Kampanya, 'Ashes Before The South' adlı ilk ciltte Chavel Yarışları ile açılır. Ekip, Veridus'un sürücüsü Fenzo Verrori ile karşılaşır. Ayrton'un yarışçı kimliği ve ekibin hızla yükselen şöhreti bu oturumlarda şekillenir.","chars":["Aldric Vorn Arkwright","Ayrton Octappen","Fenzo Verrori"],"places":["Chavel"],"factions":["The Last Bad Decision","Veridus"],"cons":"Ekibin ilk ortak macerası; yarış teması Ayrton'un (Narnia yarışı, F3 kupaları) hikâyesinin temelini kurar.","major":false,"src":["FRP Olanlar","Aldric Campaign Chronicle"],"unc":false,"note":null,"era":"cilt1","tier":"modern","img":null},{"o":106,"date":"Cilt I — Session 5","big":"Cilt I","num":false,"title":"Sedonia, Askar Kütüphanesi ve Serilda","desc":"Session 5'te Sedonia ('ihaleyi aldığım' kişi), Asgar/Askar Üniversitesi-Kütüphanesi, Stefen, Jessie ve vampir Vagor kayıtlara geçer. Handa Aldric'in ellerinde büyü uyanır ve 'İmparatorun Ateşi' kitabı ortaya çıkar. Aldric'in kurtardığı sağır-dilsiz, kimsesiz küçük kız Serilda (Serylda) da bu oturumda sahneye girer: 'Küçük kızın ismi serilda, ailesi alis ve bob.'","chars":["Aldric Vorn Arkwright","Sedonia","Stefen","Jessie","Vagor","Serylda","Alis","Bob"],"places":["Balahnur","Askar Üniversitesi-Kütüphanesi"],"factions":["The Last Bad Decision"],"cons":"Büyüyü reddeden Aldric'in ellerinde büyü uyanır. Serylda Aldric'in hayatına girer ve zamanla onu 'baba' diye çağıracaktır. Sedonia'nın kimliği ve sonraki ölümü Aldric–River ilişkisinin en büyük açık sorusu olur.","major":true,"src":["FRP Olanlar"],"unc":false,"note":null,"era":"cilt1","tier":"modern","img":{"src":"assets/art/46_Balahnur.webp","w":1280,"h":543,"kind":"user"}},{"o":107,"date":"Cilt I — [1/6/2026 oturumu]","big":"Cilt I","num":false,"title":"Ebon Passage: False Hydra ve Aldric'in ölümü","desc":"Ebon Passage'da insanlar kaybolmaktadır. Ekip bir kasap dükkânından kanlı bir mağaraya ve doğum keselerine uzanan izleri takip eder; arkasında hafızaları silen bir False Hydra vardır. Aldric Aerofall Trimatus ile bir intihar dalışı yapar ve ölür. Ayrton polymorph ağıyla onun ardından atlar.","chars":["Aldric Vorn Arkwright","Ayrton Octappen"],"places":["Ebon Passage"],"factions":["The Last Bad Decision"],"cons":"False Hydra yenilir; Aldric ölür (iki gün sonra diriltilecek). Hydra'nın ses telleri ve derisi sonradan Serylda'nın işitme ve sesini geri vermek için kullanılır.","major":true,"src":["FRP Olanlar","Aldric Campaign Chronicle"],"unc":false,"note":null,"era":"cilt1","tier":"modern","img":{"src":"assets/art/03_Aerofall_Trimatus.webp","w":1024,"h":559,"kind":"user"}},{"o":108,"date":"Cilt I — [1/8/2026 oturumu]","big":"Cilt I","num":false,"title":"Diriliş ve Güney İmparatorluğu kapsülü","desc":"Aldric iki diriliş parşömeniyle hayata döndürülür. Prof. Justinyanus cesede saygısızlık eder. Stefen, Güney İmparatorluğu hükümdarı Ankabar Jinkarin'in 'ölüme karşın' bulduğu bilgeliği taşıyan kapsülleri açıklar: 'imparatorun tüm hikmetine erişebiliriz.'","chars":["Aldric Vorn Arkwright","Prof. Justinyanus","Stefen","Ankabar Jinkarin"],"places":["Balahnur"],"factions":["The Last Bad Decision","Güney İmparatorluğu"],"cons":"Aldric geri döner. Güney kapsülleri kampanyaya girer: ekip ileride kapsül başına 30 yıl ömür çalan bu laneti açacak, Aldric de Güney'de ölümsüzlüğü seçecektir.","major":true,"src":["FRP Olanlar"],"unc":false,"note":null,"era":"cilt1","tier":"modern","img":{"src":"assets/art/48_GuneyTopraklari.webp","w":1280,"h":720,"kind":"user"}},{"o":109,"date":"Cilt I — [1/13/2026 oturumu]","big":"Cilt I","num":false,"title":"Gideon veba doktoru olur; Velocis","desc":"Gideon veba doktorlarına katılır. Aldric, Ayrton için hızlandıkça hasarı artan Velocis mızrağını yapar.","chars":["Gideon Blackwood","Aldric Vorn Arkwright","Ayrton Octappen"],"places":["Balahnur"],"factions":["Veba doktorları / Pox Masters","Ark Armatech"],"cons":"Gideon'un Pox Master / Containment Marshal kariyeri başlar. Velocis Ayrton'un imza silahı olur (Reiner Herkenoff'u bu mızrakla infaz edecek).","major":false,"src":["FRP Olanlar","V.E.L.O.C.I.S"],"unc":true,"note":"Storyboard Velocis'i Ebon Passage'dan önceye koyuyor (Aldric_60_Sahneli_Tam_Kronoloji_POV.md #14).","era":"cilt1","tier":"modern","img":null},{"o":110,"date":"Cilt I — [1/14/2026 oturumu]","big":"Cilt I","num":false,"title":"Narnia ve Ayrton'un yarışı","desc":"Dolunay Çetesi'nin lideri Ayrton'u Narnia yarışına girmeye zorlar. Ekip Xar'koth'un hiçlik portalıyla Narnia'ya geçer ve Sırat Köprüsü'nü aşar. Ayrton Narnia yarışını ve efsanevi immovable rod'u kazanır.","chars":["Ayrton Octappen","Xar'koth Val'in","Aldric Vorn Arkwright","Gideon Blackwood"],"places":["Narnia","Sırat Köprüsü"],"factions":["The Last Bad Decision","Dolunay Çetesi"],"cons":"Ayrton yarışı ve immovable rod'u kazanır; Dolunay Çetesi ile kurulan ilişki ekibi Herkenoff ağına bağlar. Narnia kapısındaki olaylar sonraki festivalin arka planıdır.","major":true,"src":["FRP Olanlar","Aldric Campaign Chronicle"],"unc":false,"note":null,"era":"cilt1","tier":"modern","img":{"src":"assets/art/54_Narnia.webp","w":1280,"h":543,"kind":"user"}},{"o":111,"date":"Cilt I — [1/15/2026 oturumu]","big":"Cilt I","num":false,"title":"Nasihir Akademisi ve Nebukadnezar","desc":"Ekip Nasihir Akademisi'ne gider. Baş Büyücü Nebukadnezar, Aldric'in parmağındaki Barışbozan yüzüğünü görür ve ona bir büyü kitabı verir.","chars":["Aldric Vorn Arkwright","Nebukadnezar"],"places":["Nasihir Akademisi"],"factions":["Nasihir Akademisi"],"cons":"Yüzüğün önemi ilk kez bir otorite tarafından fark edilir; Aldric'in büyüyle ilişkisi derinleşir.","major":false,"src":["FRP Olanlar"],"unc":false,"note":null,"era":"cilt1","tier":"modern","img":null},{"o":112,"date":"Cilt I","big":"Cilt I","num":false,"title":"Pox Sanctum: Serylda'nın sesi geri verilir","desc":"Pox Sanctum'da, False Hydra'nın ses telleri ve derisi kullanılarak runik dikişlerle Serilyda'nın (Serylda) işitme ve sesi geri verilir.","chars":["Serylda","Aldric Vorn Arkwright","Gideon Blackwood"],"places":["Pox Sanctum","Balahnur"],"factions":["Pox Masters"],"cons":"Serylda duymaya ve konuşmaya başlar. Hydra ses telleri ve Girift Alem bağlantısı ileride onun hızlı büyümesinin ve ses temelli güçlerinin (taklit, şifa sesi, Girift Çığlığı) kaynağı olur.","major":true,"src":["Aldric Campaign Chronicle","FRP Olanlar"],"unc":false,"note":null,"era":"cilt1","tier":"modern","img":{"src":"assets/art/34_Sahne3_Serylda.webp","w":1280,"h":548,"kind":"user"}},{"o":113,"date":"Cilt I — [5/13/2026 oturumu]","big":"Cilt I","num":false,"title":"40 gün 40 gece zafer festivali","desc":"Büyük Savaş'ın kazanılmasının ardından insan imparatorluğunda kırk gün kırk gece sürecek bir festival düzenlenir ('Büyük savaşın kazanılmasının ardından yapılan 40 gece 40 gün sürecek bir festival'). Festival kampanyada Narnia sonrasına denk gelir.","chars":["Aldric Vorn Arkwright","River Lane"],"places":["Balahnur"],"factions":["İmparatorluk"],"cons":"Savaş sonrası coşku dönemi; Aldric ile River'ın ilişkisi bu festivalde başlar.","major":true,"src":["FRP Olanlar"],"unc":false,"note":null,"era":"cilt1","tier":"modern","img":{"src":"assets/art/14_Ark_Armatech_Night_Festival.webp","w":1280,"h":969,"kind":"user"}},{"o":114,"date":"Cilt I — festival sırasında","big":"Cilt I","num":false,"title":"Aldric ile River Lane'in ilişkisi başlar","desc":"Kırk günlük zafer festivalinde Aldric ile mühendis River Lane arasında ilişki başlar. River mekanik bir cadı süpürgesi kullanan, oyunbaz ama mesafeli, ileride cadı olduğu anlaşılacak bir kadındır.","chars":["Aldric Vorn Arkwright","River Lane"],"places":["Balahnur"],"factions":["Ark Armatech"],"cons":"Aldric'in hayatındaki merkezî bağ kurulur: River sonradan Aldric için Vindicator tasarlar, Serylda'nın 'annesi' olur ve Aldric yüzüğü onun için yakar.","major":true,"src":["Aldric Campaign Chronicle"],"unc":false,"note":null,"era":"cilt1","tier":"modern","img":null},{"o":115,"date":"Cilt I","big":"Cilt I","num":false,"title":"Kapsül laneti ve iç sesler","desc":"Güney kapsüllerinin laneti ortaya çıkar: her kapsül açana 30 yıl ömür çalar. Gideon ve Ayrton ikinci kapsülü de açar (toplam 60 yıl), altın kum öksürürler. Aynı dönemde Aldric'in zihnindeki Thanatos ve Limbic System sesleri belirginleşir.","chars":["Gideon Blackwood","Ayrton Octappen","Aldric Vorn Arkwright"],"places":["Balahnur"],"factions":["The Last Bad Decision"],"cons":"Gideon ve Ayrton'un ömrü kısalır (Gideon'un omzu ileride kuma dönecek). Thanatos ve Limbic System kampanya boyunca Aldric'in iç dünyasının iki sesi olur.","major":true,"src":["Aldric Campaign Chronicle"],"unc":false,"note":null,"era":"cilt1","tier":"modern","img":{"src":"assets/art/37_Thanatos.webp","w":636,"h":618,"kind":"user"}},{"o":116,"date":"Cilt I — [5/13/2026 özeti]","big":"Cilt I","num":false,"title":"Aetherion Magnus ve İmparatoriçe'nin yükselişi","desc":"Aetherion Magnus hava gemisi kobolt işçilerle inşa edilir. Ekip Dolunay Çetesi'ne koruma sağlar; bir Jinn'in laneti ve bir cüce rünü kayıtlara geçer. Ayrton protez bacaklar alır; konağı goblinlerce yakılır. Ark Armatech İmparatorluğa 100 Aerofall Trimatus teslim eder. İmparator ölür ve kızı İmparatoriçe olur; bir şövalye tabutu konvoyu düzenlenir.","chars":["Aldric Vorn Arkwright","Ayrton Octappen","İmparatoriçe","İmparator"],"places":["Aetherion Magnus","Balahnur"],"factions":["Ark Armatech","Dolunay Çetesi","İmparatorluk","Goblinler"],"cons":"Aetherion Magnus ekibin amiral gemisi olur. İmparatoriçe tahta çıkar (Crownforge ayinine giden yol). Ayrton'un protez bacakları ve kaybettiği konak onun kimliğinin parçası olur.","major":true,"src":["FRP Olanlar"],"unc":false,"note":null,"era":"cilt1","tier":"modern","img":{"src":"assets/art/02_Aerofall_Trimatus_2.webp","w":1024,"h":559,"kind":"user"}},{"o":117,"date":"Cilt I","big":"Cilt I","num":false,"title":"Daria Gordon'un balosu","desc":"Gideon'un o dönemki sevgilisi Daria Gordon'un balosunda İmparatoriçe (ya da bir yakını) Aldric'e 1 milyon altınlık gizli bir ada anlaşması teklif eder.","chars":["Daria Blackwood","Gideon Blackwood","Aldric Vorn Arkwright","İmparatoriçe"],"places":["Balahnur"],"factions":["İmparatorluk","Ark Armatech"],"cons":"İmparatorluk ile Ark Armatech arasındaki gizli bir ada projesi gündeme gelir; Crownforge adası tarafındaki gelişmelerin olası bir öncüsü (çıkarım).","major":false,"src":["Aldric Campaign Chronicle"],"unc":false,"note":null,"era":"cilt1","tier":"modern","img":null},{"o":118,"date":"Cilt I — [5/14/2026 oturumu]","big":"Cilt I","num":false,"title":"Güneye sefer ve Gideon'un kurtarılışı","desc":"Ekip Blavinken'den bir balıkçı köyüne, oradan güney kıtasına sefer yapar. Gideon'un omzu kapsül laneti yüzünden kuma döner; Aldric'in dark meter'ı 10/10'a çıkar ve onun için S.A.R.M. protezini yapar. Yolda Volansar kuşları görülür. Antik bir fener kulesi Aetherion'u vurur. Trader'ın zorlamasıyla Gideon, balonu yakan küreyi yerleştirerek sabotaj yapar; Aldric düşen Gideon'u gökten kurtarır. Ayrton'a göre Aldric onu bilerek kurtarmıştır.","chars":["Aldric Vorn Arkwright","Gideon Blackwood","Ayrton Octappen","Trader"],"places":["Blavinken","Balıkçı köyü","Güney Toprakları"],"factions":["The Last Bad Decision"],"cons":"Gideon S.A.R.M. protezini kazanır; Aldric–Gideon dostluğu karşılıklı kurtarma üzerine kurulur. Trader'ın bedel isteyen pazarlıkları kampanyaya girer.","major":true,"src":["Aldric Campaign Chronicle","FRP Olanlar"],"unc":false,"note":null,"era":"cilt1","tier":"modern","img":{"src":"assets/art/48_GuneyTopraklari.webp","w":1280,"h":720,"kind":"user"}},{"o":119,"date":"Cilt I sonu","big":"Cilt I sonu","num":false,"title":"Kırmızı kumlarda yalnızlık ve 'Sedonia öldü'","desc":"Gideon'u kurtardıktan sonra Aldric ekipten ayrılır ve Güney'in kırmızı kum tepelerinde tek başına yürür: 'Belki de bu lanetten kurtulmalarının tek yolu… bensiz olmaları.' Bu sırada River'dan bir mektup gelir: 'Sedonia öldü. Artık Ark Armatech'i ve bizi rahatsız edemeyecek.' Gideon ve Ayrton'u çöl haydutları izlemeye başlar. Cilt I burada biter.","chars":["Aldric Vorn Arkwright","River Lane","Sedonia","Gideon Blackwood","Ayrton Octappen"],"places":["Güney Toprakları"],"factions":["The Last Bad Decision","Çöl haydutları"],"cons":"Aldric'in kendini suçlama ve uzaklaşma eğilimi belirginleşir. Mektubun 'gereğinden fazla rahat' cümlesi ve River'ın cadılığı ileride Aldric'in güvenini sarsar.","major":true,"src":["Aldric Campaign Chronicle","Wisdom That Chokes You"],"unc":false,"note":null,"era":"cilt1","tier":"modern","img":null},{"o":120,"date":"Cilt I sonu ile TimeSkip 1 arası","big":"Cilt I sonu ile TimeSkip 1…","num":false,"title":"Katip Pirdeviz'in piramidi: ölümsüzlük","desc":"Güney Toprakları'nda Aldric, kendini bir piramidin içine mühürlemiş kadim ve ölümsüz (undead) saray kâtibi Katip Pirdeviz ile karşılaşır. Pirdeviz, Güney İmparatorluğu hükümdarı Ankabar Jinkarin'in kâtibidir. Aldric'e seçebileceği bir ödül/hikmet sunar ve Aldric ölümsüzlüğü seçer. Olay yazılı hikâyelerde sahnelenmez; Aldric'in Revalor'a mektubunda anılır. Revalor'a yazdığı mektupta Aldric bunu şöyle anar: 'tozla kaplı parmaklarıyla önümdekileri gösterdi ve ben ölümsüzlüğü seçtim. O gün bunun bir zafer olduğunu sandım. Şimdi bir yük olduğunu biliyorum.'","chars":["Aldric Vorn Arkwright","Katip Pirdeviz","Ankabar Jinkarin"],"places":["Güney Toprakları","Katip Pirdeviz'in piramidi"],"factions":["Güney İmparatorluğu"],"cons":"Aldric ölümsüz olur. Bu, sevdiklerinin yaşlanacağı korkusunu, River ile Serylda'nın ömrüyle eşitlenme arayışını ve Revalor'dan zaman dışı bir sığınak isteğini doğurur.","major":true,"src":["Aldric’in Revalor’a mektubu"],"unc":true,"note":"Yer çıkarım: Cilt I sonu ile TimeSkip1 arası. 'Pirdeviz', 'piramit' ve 'kâtip' hiçbir dosyada geçmiyor; tek yazılı kaynak Aldric'in Revalor'a mektubu.","era":"cilt1","tier":"modern","img":null},{"o":121,"date":"TimeSkip 1 Part 1 ('hayatını değiştiren toplantı'dan ~2 hafta sonra)","big":"TimeSkip 1 Part 1","num":false,"title":"Soyulma, Bitliayak Hanı ve beyaz oda","desc":"Güney'den Balahnur'a dönüş yazılı değil. Balahnur'da Ark Armatech kraliyet bölgesinde yeni bir atölye açmıştır; İmparatorluğa 98 gemi verilmiştir, Murat Bey atölye yöneticisidir ve enerji kapsülü stabil değildir. Aldric bir ara sokakta yaralanıp soyulur. Bir köylü çift onu patates arabasıyla Bitliayak Hanı'na satmaya götürür; orada zincirlenip dövülür ('O gün senin atölyende kaç kişiyi kaybettik'). Siyah giyimli bir birlik onu bir 'paket' olarak alır ve beyaz bir odada sırtına ameliyat yapılır. Bu sırada çocukluk anıları geri gelir.","chars":["Aldric Vorn Arkwright","Murat Bey"],"places":["Balahnur","Bitliayak Hanı","Beyaz oda"],"factions":["Ark Armatech","İmparatorluk"],"cons":"Aldric ortadan kaybolur. Sırtına yapılan ameliyat, Part 2'de takılacak elf omurga sisteminin başlangıcıdır. Atölye kazalarının halktaki öfkesi ortaya çıkar.","major":true,"src":["The Arkwright Chronicles","TimeSkip 1"],"unc":false,"note":null,"era":"ts1","tier":"modern","img":{"src":"assets/art/07_Ark_Armatech_Atolye.webp","w":1280,"h":720,"kind":"user"}},{"o":122,"date":"TimeSkip 1 Part 2 (2 aylık atlama)","big":"TimeSkip 1 Part 2","num":false,"title":"Elf omurga sistemi ve Gideon'un kurtarması","desc":"Herkenoff'lardan biri Aldric'i satın alır; Ratarr Order eliyle bir elf tesisine götürülür. Elf Ilrune Araxsys, Kral Revalor Olawarin'in emriyle sırtına 'Elven Magical Spinal System' takar. Gideon (69. Cadde Pox Master karakolu, yardımcısı William Bucks) onu bulur. Birlikte bir taburu aşıp kaçarlar.","chars":["Aldric Vorn Arkwright","Gideon Blackwood","Ilrune Araxsys","Revalor Olawarin","William Bucks"],"places":["Elf tesisi","Balahnur","69. Cadde Pox Master karakolu"],"factions":["Herkenoff ailesi","Ratarr Order","Pox Masters","Elfler"],"cons":"Aldric'in sırtında artık elf omurga sistemi var ('Vertebra incipere' ile algıyı hızlandırma). Revalor ile ilk dolaylı bağ kurulur. Gideon Aldric'in hayatını kurtarır.","major":true,"src":["The Arkwright Chronicles","TimeSkip 1"],"unc":false,"note":null,"era":"ts1","tier":"modern","img":{"src":"assets/art/17_Gideon_v2.webp","w":960,"h":1280,"kind":"user"}},{"o":123,"date":"Time skip sırasında","big":"Time skip sırasında","num":false,"title":"Julius Vane Ark Armatech'e katılır","desc":"Murat Bey ozan Julius Vane'i bulur; Aldric onu Ark Armatech'in reklamları için işe alır. 'Silver Voice' kimliğiyle tanınan Julius'un anlattığı kahramanlık hikâyeleri (10 yıllık savaş, Trickster God'u kandırması, Barışbozanların düşüşü) yalandır. River bir okul etkinliği için onun eleman bulmasını ister; Julius mavi saçlı müzisyen Amber ile tanışır. Geçmişi acıdır: The Hundred Blades dört yıl önce köyünü yakmış, Julius annesini ve sevgilisi Anastasia'yı koruyamamıştır.","chars":["Julius Vane","Murat Bey","Aldric Vorn Arkwright","River Lane","Amber","Anastasia"],"places":["Ark Armatech","Balahnur"],"factions":["Ark Armatech","The Hundred Blades"],"cons":"Julius Ark Armatech çevresine girer ve ileride The Last Bad Decision'ın üyesi olur. Hundred Blades ve kayıp Anastasia onun intikam yayının tohumudur.","major":true,"src":["Julius Vane hikâyesi"],"unc":true,"note":"Hangi time skip olduğu belirtilmiyor; TimeSkip 2'de Julius zaten Ark Armatech konseyinde.","era":"ts1","tier":"modern","img":{"src":"assets/art/19_JuliusVane.webp","w":557,"h":821,"kind":"user"}},{"o":124,"date":"Yıllardır süren arka plan (Julius III'te açığa çıkar)","big":"Yıllardır süren arka plan","num":false,"title":"Julius'un Nyxara ile anlaşması","desc":"Julius, Nyxara adlı bir iblisle bilerek anlaşma yapmıştır. Her şarkısı ve her feda iblise güç ve canlılık verir; karşılığında Julius yavaş yavaş duygusuzlaşır ('Hollow Voice'). Feda ettikleri arasında adı geçmeyen bir kız, bir maceracı ve rap düellosunda kendisine yenilip peşine takılan cüce ozan Mininem Slimshieldy vardır.","chars":["Julius Vane","Nyxara","Mininem Slimshieldy"],"places":["Nyxara'nın ini"],"factions":["Nyxara"],"cons":"Anlaşma Julius'un tüm sonraki düşüşünün kaynağıdır: lonca üyelerini feda etmesi, 12 şarkı, 13. şarkı tuzağı ve sonunda kendi boğazını kesmesi.","major":true,"src":["Julius Vane hikâyesi"],"unc":true,"note":"Başlangıç tarihi belirsiz ('yıllardır').","era":"ts1","tier":"modern","img":null},{"o":125,"date":"TimeSkip 1 Part 2 sonrası, tahliye öncesi","big":"TimeSkip 1 Part 2 sonrası,…","num":false,"title":"Cedric avı ve Aldric'in tehdidi","desc":"Aldric, Ayrton, Gideon, Levi ve Gideon'un askeri Tom, Herkenoff çetesinden Cedric'i avlar. Aldric ölmekte olan adamı ailesi ve mezarı üzerinden acımasızca tehdit eder. Bu tutum Levi ile Tom'u ondan uzaklaştırır. Aldric sonra günlüğünde 'Levi ile Tom'un benden uzaklaşmasını anlıyorum' diye yazar. Arka plan (Kaynak: Gideon Blackwood hikâyesi): Cedric'in çocukları ghoul'a dönüşmüş ve onları kendisi öldürmüştür.","chars":["Aldric Vorn Arkwright","Ayrton Octappen","Gideon Blackwood","Levi","Tom","Cedric"],"places":["Balahnur"],"factions":["The Last Bad Decision","Herkenoff ailesi","Pox Masters"],"cons":"Cedric yakalanır; Aldric'in karanlık yüzü ekibe görünür ve Levi ile Tom ondan uzaklaşır. Herkenoff'a karşı mücadele derinleşir.","major":true,"src":["FRP Notları","Yük Dağılımı","Gideon Blackwood hikâyesi"],"unc":true,"note":"Kesin yeri belirsiz (Part 2 sonrası, tahliye öncesi).","era":"ts1","tier":"modern","img":{"src":"assets/art/18_Gideon_Maskesiz.webp","w":852,"h":1280,"kind":"user"}},{"o":126,"date":"TimeSkip 1 sonrası (FRP NOTES 1–2)","big":"TimeSkip 1 sonrası","num":false,"title":"Prof. Jephcoats ve Cogito Rezonans cihazı","desc":"Prof. Jephcoats'ın Cogito Rezonans cihazı Serilyda'yı (Serylda) denek olarak seçer. Aldric Jephcoats'ı 'öldürür'. Jephcoats'ın evinde gizli bir oda, Crisp-tease ve mektuplar bulunur. (Not: FRP NOTES, Ayrton'un yaratık formunun Ark Armatech'e saldırısını da bu döneme koyuyordu; kronolojide saldırı Crownforge ayininden kısa süre önceye yerleştirilmiştir, bkz. 'Ayinden önceki günler'.)","chars":["Aldric Vorn Arkwright","Prof. Jephcoats","Serylda","Crisp-tease"],"places":["Balahnur","Jephcoats'ın evi"],"factions":["The Last Bad Decision"],"cons":"Serylda'yı hedef alan tehdit bertaraf edilir. Gizli oda ve mektuplar, Girift Alem astral yolculuğuna ve Crisp-tease ile kurulan bağa kapı açar. TimeSkip 2'de Jephcoats ölü olarak anılır.","major":true,"src":["FRP Notları"],"unc":false,"note":null,"era":"ts2","tier":"modern","img":null},{"o":127,"date":"TimeSkip 2 kışı — Gün 1–27 (Balahnur düşmeden önce)","big":"TimeSkip 2 kışı","num":false,"title":"Ayrton Herkenoff'a sızar","desc":"Ayrton eski ekibinden ayrılmış gibi yapar ve Levi'yi 'kız arkadaşı' olarak yanına alıp Herkenoff örgütüne girer. Gideon'a bir not bırakarak ikizler Rem ve Ram'ı korumasını ve onları Ark Armatech'te işe aldırmasını ister. Murat Bey aracılığıyla Aldric'e teşekkür hediyeleri bırakır. Dilar ile bağlantı kurar. Ruh yüzüğü ve sabotajlarla Fedai rütbesinden Reis'e yükselir; bu süreçte bir Reis'in kafasını ısırarak koparır.","chars":["Ayrton Octappen","Levi","Gideon Blackwood","Rem","Ram","Murat Bey","Aldric Vorn Arkwright","Dilar"],"places":["Balahnur"],"factions":["Herkenoff ailesi","The Last Bad Decision","Ark Armatech"],"cons":"Ayrton Herkenoff'un içinde Reis olur ve örgüt içeriden çökertilmeye başlanır. Rem ve Ram Ark Armatech'e emanet edilir.","major":true,"src":["Ayrton Octappen hikâyesi"],"unc":false,"note":null,"era":"ts2","tier":"modern","img":{"src":"assets/art/41_Ayrton.webp","w":853,"h":1280,"kind":"user"}},{"o":128,"date":"TimeSkip 2 kışı","big":"TimeSkip 2 kışı","num":false,"title":"Görev dağılımı ve Gideon'a isimsiz zarflar","desc":"Ayrton, Herkenoff'un iki kolu olan Avcılar ve Toplayıcılar hakkında Gideon'a isimsiz zarflar gönderir. Görev dağılımı şöyle yapılır: Levi → Waclaw; Gideon → Cedric/Toplayıcı bilgisi; Aldebaran → Erdan Lilov; Ayrton → The Judge; Dilar ve yüzük → Keira Pirus.","chars":["Ayrton Octappen","Gideon Blackwood","Levi","Aldebaran","Dilar"],"places":["Balahnur"],"factions":["Herkenoff ailesi","Pox Masters"],"cons":"Herkenoff'un liderlerine karşı koordineli bir av başlar; bu ağ kıyamet gecesindeki malikâne baskınıyla sonuçlanacaktır.","major":false,"src":["Ayrton Octappen hikâyesi","Gideon Blackwood hikâyesi"],"unc":false,"note":null,"era":"ts2","tier":"modern","img":null},{"o":129,"date":"TimeSkip 2 kışı — Gün 1–40","big":"TimeSkip 2 kışı","num":false,"title":"Ayrton'un sinomorph'ları uyanır","desc":"Ayrton'un içindeki günah biçimli güçler (sinomorph'lar) art arda uyanır. Vanity: F2 dayanıklılık yarışı, Herkenoff karışımı ve Mâverâ-yı Mekân. Gluttony (Gün 1–14): anıları yiyebilme ve 5 gün içinde kaybolma. Melancholy & Sloth (Gün 20): kurt adamlar bir Fedai'nin ailesine saldırır, zihninde Omux ona yardım eder. Wrath (Gün 26): Levi'yi döven 7 Fedai'yi katleder. Lust (Gün 32): Lierin, Dilar ve Omux'un yer aldığı bölüm; Levi ile ilişkisi bu noktada başlar (yalnızca olay düzeyinde). Greed (Gün 40): sevdiklerinin ölümcül acısını üstlenir; 4 kalıntılık bir soygunda 3'ünü çalarlar; Ayrton ölür ve 'yabancı bir hayat' ile mutagen sayesinde dirilir.","chars":["Ayrton Octappen","Levi","Omux","Dilar","Lierin"],"places":["Balahnur","Mâverâ-yı Mekân"],"factions":["Herkenoff ailesi"],"cons":"Ayrton'un güçleri ve bedelleri belirginleşir; Levi ile ilişkisi başlar. Ölüp mutagenle dirilmesi, sonraki Pride taşmasının ve yaratık formunun zeminidir.","major":true,"src":["Ayrton Octappen hikâyesi","Olay özetleri"],"unc":false,"note":null,"era":"ts2","tier":"modern","img":{"src":"assets/art/42_Ayrton_Octappen_2.webp","w":853,"h":1280,"kind":"user"}},{"o":130,"date":"Balahnur sağlam, kış (kesin yeri belirsiz)","big":"Balahnur sağlam, kış","num":false,"title":"Gideon'un Balahnur vakaları","desc":"Containment Marshal Gideon Happy Faces hanındaki cinayetleri çözer. İzler Tom Barehand'e, William'a, 67. Cadde'ye, kurtboğan otuna, oyuncak bir attaki sembole ve eski Pox Sanctum tünellerine uzanır. Fail kurt adam Jonas Bell'dir; yanında büyük olasılıkla oğlu olan ~9 yaşında bir çocuk vardır. Dava kapanır ama 'av yeni başlıyor'. Ardından vampir çocuk Saul Gortsky vakası gelir. Geciken erzak yüzünden kışın Beaver sokağında isyan çıkar; Gideon Ercan'dan 3000 altına odun alır. Donanmanın Man o' War gemisine bir minotor saldırır. Daria Gordon'un kolyesi meselesi yaşanır ve Gideon Pox Sanctum havuzunda iyileşir.","chars":["Gideon Blackwood","Tom Barehand","William Bucks","Jonas Bell","Saul Gortsky","Ercan","Daria Blackwood"],"places":["Balahnur","Happy Faces hanı","67. Cadde","Beaver sokağı","Pox Sanctum"],"factions":["Pox Masters","İmparatorluk donanması"],"cons":"Gideon'un şehirdeki otoritesi ve Containment Marshal kimliği pekişir. Erzak krizi Balahnur'un çöküşe gittiğini gösterir.","major":true,"src":["Gideon Blackwood hikâyesi"],"unc":true,"note":"Kesin yeri belirsiz (Balahnur sağlam, kış).","era":"ts2","tier":"modern","img":{"src":"assets/art/28_Sahne1.webp","w":1280,"h":548,"kind":"user"}},{"o":131,"date":"Yer belirsiz","big":"Yer belirsiz","num":false,"title":"Gideon ve Daria — 'Off Duty'","desc":"Gideon ile Daria'nın ilişkisini ve evliliğini anlatan 'Off Duty' bölümleri (Gideon Chapter I–V). Bölüm V yetişkin içeriklidir; burada yalnızca olay düzeyinde anılır: ikili arasındaki bağ evliliğe dönüşür.","chars":["Gideon Blackwood","Daria Blackwood"],"places":["Balahnur"],"factions":[],"cons":"Daria Gordon, Daria Blackwood olur. Bu bağ, Daria'nın cadı olduğunu açıkladığı anda Gideon'u görev ile karısı arasında bırakacaktır.","major":false,"src":["Gideon Blackwood hikâyesi","Olay özetleri"],"unc":true,"note":"Yer belirsiz.","era":"ts2","tier":"modern","img":null},{"o":132,"date":"TimeSkip 2 — kış","big":"TimeSkip 2","num":false,"title":"TimeSkip 2: 'The Weight Beneath the Crown'","desc":"Jephcoats ölmüştür. Barışbozan yüzüğünden üçüncü bir ses konuşmaya başlar: kendini 'Yüce Boraldmir'in hizmetkârı' olarak tanıtan Tamrill Ar Aserihn. Project Crownforge adasında 7 haftalık bir seçim süreci yürür (Hughbert Pepperfield, Aday 832). Aldric The Grafted birliğini kurar (Forge, Null, Veyr, Hound). Ark Armatech acil konseyi toplanır: River, Daria Blackwood, Murat Bey ve Julius Vane.","chars":["Aldric Vorn Arkwright","Tamrill Ar Aserihn","Hughbert Pepperfield","Forge","Null","Veyr","Hound","River Lane","Daria Blackwood","Murat Bey","Julius Vane"],"places":["Balahnur","Crownforge Adası","Ark Armatech"],"factions":["Ark Armatech","Project Crownforge","The Grafted","Boraldmir"],"cons":"Boraldmir'e bağlı bir ses Aldric'in zihnine girer. Crownforge seçimi İmparatoriçe'nin ayinine giden yolu açar. The Grafted, Serylda'nın eğitiminde ve ElfAdası döneminde rol oynayacak bir birlik olur.","major":true,"src":["TimeSkip 2","Project Crownforge","The Grafted"],"unc":false,"note":null,"era":"ts2","tier":"modern","img":{"src":"assets/art/24_Island.webp","w":1280,"h":853,"kind":"user"}},{"o":133,"date":"TimeSkip 2 sonrası","big":"TimeSkip 2 sonrası","num":false,"title":"Vindicator Mk.I ve 'Balahnur'un Üzerinde Bir Gece'","desc":"Vindicator Mk.I tamamlanır. Araştırma defterinde Aldric, Tamrill'e 'Bir daha yardım edersen yüzüğü eritirim' der. 'Balahnur'un Üzerinde Bir Gece' hikâyesinde Aldric ile River Aetherion'da bir gece geçirir. Yüzük çekmeceye kilitlenir ve Sedonia tartışması kapanır. (Bölüm IV yetişkin içeriklidir; yalnızca olay düzeyinde anılır.)","chars":["Aldric Vorn Arkwright","River Lane","Tamrill Ar Aserihn"],"places":["Aetherion Magnus","Balahnur"],"factions":["Ark Armatech"],"cons":"Aldric'in imza zırhı hazır olur. Sedonia meselesi Aldric ile River arasında kapanır ve yüzükten kurtulma kararının ilk adımı atılır.","major":true,"src":["Vindicator kayıtları","Olay özetleri"],"unc":false,"note":null,"era":"ts2","tier":"modern","img":{"src":"assets/art/39_AldricwVindicator.webp","w":1280,"h":548,"kind":"user"}},{"o":134,"date":"Crownforge'dan sonra, Balahnur'un yanışından önce","big":"Crownforge'dan sonra,…","num":false,"title":"Yüzüğün yakılması ve 'Echoes of the Past'","desc":"Aldric Barışbozan yüzüğünü ateşe verir. Elinde taze yanık izleriyle River'la birlikte Blavinken ormanlarındaki, River'ın zamanda donmuş ailesinin evine gider. Orada bir ghoul sürüsüyle savaşırlar. River'ı kurtarırken kasksız çarpıp yaralanır; uyanınca River'a 'Ben senin için dünyayı yakarım' der. 'Yüzüğü yaktığımda bir şeyin bittiğini düşünmüştüm… Yüzük bitti.' Yakma anı hiçbir dosyada sahnelenmemiş, yalnızca sonrası anlatılıyor.","chars":["Aldric Vorn Arkwright","River Lane","River'ın ailesi"],"places":["Blavinken ormanları","River'ın ailesinin evi"],"factions":[],"cons":"Barışbozan yüzüğü ve Tamrill'in sesi Aldric'in hayatından çıkar; sağ elinde yanık izi kalır. River'ın geçmişi (zamanda donmuş aile) açığa çıkar ve ilişki derinleşir.","major":true,"src":["Echoes of the Past"],"unc":true,"note":"Echoes Crownforge'dan sonra, Balahnur'un yanışından önce (çıkarım: Balahnur sağlam).","era":"ts2","tier":"modern","img":{"src":"assets/art/35_Rivern_evi.webp","w":1280,"h":698,"kind":"user"}},{"o":135,"date":"TimeSkip 2 dönemi (yeri tartışmalı)","big":"TimeSkip 2 dönemi","num":false,"title":"Girift Alem astral yolculuğu ve 'Oath of The Ninth'","desc":"Crisp-tease ile Girift Alem'e astral bir yolculuk yapılır: tutulmuş bir güneş, uçan denizanaları, beyaz saçlı bir kadın ve açılmayan bir sandık. İnsan derisi üzerine yazılmış 'Oath of The Ninth' bulunur.","chars":["Aldric Vorn Arkwright","Crisp-tease","Beyaz saçlı kadın (Girift-alem cadısı)"],"places":["Girift Alem"],"factions":["Cadılar"],"cons":"Beyaz saçlı kadın ileride Crownforge ayininde İmparatoriçe'yi ve Kutsal Elma'yı alacak Girift-alem cadısıdır. Cadıların Girift Alem'deki tutulma yeriyle ilgisi kampanyanın sonraki olaylarında önem kazanır.","major":true,"src":["FRP Notları"],"unc":true,"note":"FRP NOTES bunu Jephcoats araştırmasının hemen ardından anlatıyor; storyboard ise Vindicator/Echoes'tan sonraya koyuyor.","era":"ts2","tier":"modern","img":{"src":"assets/art/00_9thWitch.webp","w":748,"h":365,"kind":"user"}},{"o":136,"date":"TimeSkip 2 — Gün 46","big":"TimeSkip 2","num":false,"title":"Ayrton – Envy: Doktor Einshmirtz","desc":"Ayrton eski bir malikâneye kaçırılır. Doktor Einshmirtz, Ark Armatech üzerinden devletin sırlarını öğrenmek için Aldric'in beynini açmak ister. Alfa kurt adam Quillclaw, Reis Magnus ve Müdür Vincent ölür; Ayrton anti-polimorf karışımı 'Polymorph: Hemorrphology'yi kullanır. Doktor, Ayrton'u bir susma anlaşmasına zorlar. Anlaşma gizli kalır.","chars":["Ayrton Octappen","Doktor Einshmirtz","Quillclaw","Reis Magnus","Müdür Vincent","Aldric Vorn Arkwright"],"places":["Eski malikâne"],"factions":["Herkenoff ailesi"],"cons":"Einshmirtz, Aldric'i hedef alan gizli bir tehdit olarak ortaya çıkar; Ayrton'un susma anlaşması yüzünden bu tehdit gizli kalır.","major":true,"src":["Ayrton Octappen hikâyesi"],"unc":false,"note":null,"era":"ts2","tier":"modern","img":{"src":"assets/art/41_Ayrton.webp","w":853,"h":1280,"kind":"user"}},{"o":137,"date":"TimeSkip 2","big":"TimeSkip 2","num":false,"title":"Ayrton – Pride","desc":"Mutagen sınırı aşılır. Ayrton günlerce kendi zihnine hapsolur; Pride tamamen tezahür eder ve diğer günahları susturur.","chars":["Ayrton Octappen"],"places":["Ayrton'un zihni"],"factions":[],"cons":"Pride/mutagen taşması, Ayrton'un yaratık formunun Ark Armatech'e saldırmasına yol açar.","major":true,"src":["Ayrton Octappen hikâyesi","Olay özetleri"],"unc":false,"note":null,"era":"ts2","tier":"modern","img":{"src":"assets/art/22_Pride.webp","w":1024,"h":1280,"kind":"user"}},{"o":138,"date":"Crownforge ayininden kısa süre önce","big":"Crownforge ayininden kısa…","num":false,"title":"Ayinden önceki günler: yaratık saldırısı ve Julius'un daveti","desc":"Amber'in utangaç, turuncu saçlı arkadaşı Ester sahneye girer. Şehirde cadı infazları yapılır. Gideon bir 'abominasyon'la dövüşür; Julius kaçar. Pride/mutagen taşması sonrası Ayrton'un yaratık formu Ark Armatech'e saldırır ve geri döner. Julius'un illüzyon klonu yaralı Daria'yı tahliye eder; Gideon yaratığı yener ve altından bir insan, yani Ayrton çıkar. Julius handa bir şarkıyla itirafta bulunur; Gideon ve Aldric onu The Last Bad Decision'a davet eder. Julius bir Inu'ya (lirkuşu) dönüşür ('Ben meyve yemedim ki!'); Gideon Inu'ların görüldükleri yerde infaz edildiğini söyler. Bir rahip iblis varlığını sezer.","chars":["Julius Vane","Amber","Ester","Gideon Blackwood","Ayrton Octappen","Daria Blackwood","Aldric Vorn Arkwright"],"places":["Balahnur","Ark Armatech","Han"],"factions":["The Last Bad Decision","Cadılar","Pox Masters"],"cons":"Julius The Last Bad Decision'a katılır. Ayrton insan formuna döner. Inu dönüşümleri ilk kez yakın çevrede görülür ve Julius'taki iblis izi (Nyxara) bir rahip tarafından sezilir.","major":true,"src":["Julius Vane hikâyesi"],"unc":false,"note":null,"era":"ts2","tier":"modern","img":{"src":"assets/art/20_LAST_BAD_DECISION.webp","w":853,"h":1280,"kind":"user"}},{"o":139,"date":"TimeSkip 2 sonu (FRP NOTES 3)","big":"TimeSkip 2 sonu","num":false,"title":"Crownforge ayini: Seraphim'in doğuşu ve düşüşü","desc":"Velina Aldric'i Crownforge adasına götürür. İmparatoriçe Aldric'i öpmeye çalışır ve reddedilir. Ayin 'Probatio Ascensionis in Angelum'dur. İmparatoriçe, Aldric ve River ayini Julius ile Serylda'dan ister; ikisinin şarkısıyla Seraphim doğar ve düşer. Herkes cadı çıkar. Girift-alem cadısı (beyaz saçlı kadın) İmparatoriçe'yi ve Kutsal Elma'yı alır. Pride düşmüş meleği Balahnur'a yollar. Ekip River'ın portalı ve bir Flash canister ile kaçar.","chars":["Aldric Vorn Arkwright","Velina","İmparatoriçe","River Lane","Julius Vane","Serylda","Seraphim","Girift-alem cadısı","Pride"],"places":["Crownforge Adası"],"factions":["İmparatorluk","Cadılar","The Last Bad Decision"],"cons":"İmparatorluk sarayı cadılarla dolu çıkar. İmparatoriçe ve Kutsal Elma kaybedilir. Düşmüş melek Balahnur'a yönelir; bu, Balahnur'un yanışının doğrudan başlangıcıdır.","major":true,"src":["FRP Notları","Julius Vane hikâyesi"],"unc":false,"note":null,"era":"ts2","tier":"modern","img":{"src":"assets/art/25_Seraphim.webp","w":721,"h":1280,"kind":"user"}},{"o":140,"date":"Crownforge ayininin ardından","big":"Crownforge ayininin ardından","num":false,"title":"Balahnur yanar","desc":"Düşmüş melek Balahnur'a gelir ve şehir yanar. River lanetlidir. Julius, Serylda'yı kurtarıp kendini cadılara feda eder. İşçiler Inu'ya dönüşmeye başlar. Gideon Pox Master'larla İmparatorluğa karşı ayaklanır. Ark Armatech şehrin son kalesi olur.","chars":["River Lane","Julius Vane","Serylda","Gideon Blackwood","Aldric Vorn Arkwright"],"places":["Balahnur","Ark Armatech"],"factions":["Cadılar","Pox Masters","İmparatorluk","Ark Armatech"],"cons":"Balahnur çöker. Julius cadıların esiri olur, River lanetlenir. Pox Masters ile İmparatorluk karşı karşıya gelir ve Ark Armatech halkın sığınağı olur.","major":true,"src":["FRP Notları"],"unc":false,"note":null,"era":"dusus","tier":"modern","img":{"src":"assets/art/12_Balahnur_gece.webp","w":1280,"h":720,"kind":"user"}},{"o":141,"date":"Balahnur'un düşüşü sırasında","big":"Balahnur'un düşüşü sırasında","num":false,"title":"Julius cadıların elinde","desc":"Julius ve Serylda cadıların elinde esirdir. Julius'a işkence edilir ve günlerce şarkı söyletilir. Bu bölüm, Julius ile Serylda arasındaki ve ayrıntısı kayıtlarda yer almayan gizli olayı da içerir.","chars":["Julius Vane","Serylda"],"places":["Cadıların esir yeri"],"factions":["Cadılar"],"cons":"Julius'un sesi günlerce şarkı söylemekten tükenir. Julius ile Serylda arasındaki gizli olay gizli kalır.","major":false,"src":["Julius Vane hikâyesi"],"unc":false,"note":null,"era":"dusus","tier":"modern","img":null},{"o":142,"date":"Balahnur'un düşüşü sırasında (yer çıkarım)","big":"Balahnur'un düşüşü sırasında","num":false,"title":"Daria cadı olduğunu açıklar","desc":"Zindanda Daria, Gideon'a artık bir cadı olduğunu söyler. Gideon görevi ile karısı arasında kalır. (Olay özeti; sahnede üçüncü kişiler Daria'nın iradeyi bastıran büyüsü altındadır ve Gideon'un muhakemesi de büyüyle bulanıktır.)","chars":["Daria Blackwood","Gideon Blackwood","Tom"],"places":["Zindan","Balahnur"],"factions":["Cadılar","Pox Masters"],"cons":"Gideon'un en yakın bağı düşman safına geçer; Containment Marshal ile cadı eşi arasındaki çatışma açılır.","major":true,"src":["Gideon Blackwood hikâyesi","Olay özetleri"],"unc":true,"note":"Yer çıkarım.","era":"dusus","tier":"modern","img":{"src":"assets/art/18_Gideon_Maskesiz.webp","w":852,"h":1280,"kind":"user"}},{"o":143,"date":"Kıyamet gecesi","big":"Kıyamet gecesi","num":false,"title":"Herkenoff malikânesi baskını ve Daniel'in kurtarılışı","desc":"Cadılar sarayı alınca Ayrton yolda Serylda'yı bulur ve Aldric'e ulaştırır. Rem ile Ram'ı Trader'a emanet eder (Trader'a 2 borcu daha olur). Gluttony ile Levi'yi bulur ve Gideon'un harekâtına katılır. Aldebaran ile Grukh, Erdan Lilov'u indirir; Blanka Gideon'la dövüşür; Ayrton Reiner Herkenoff'u Velocis mızrağıyla infaz eder. Buzdaki 'keskinayaz' hastalığını Gideon şişeler ve Nasihir'de kara buzla dondurtur. Amanar görülünce Ayrton, Pride (Apotheosis) ve Vanity'yi feda ederek abisi Daniel Octappen'i eski hâline getirir, onu Ark Armatech'e taşır ve tünelden elf topraklarına giden portalı seçer.","chars":["Ayrton Octappen","Serylda","Aldric Vorn Arkwright","Rem","Ram","Trader","Levi","Gideon Blackwood","Aldebaran","Grukh","Erdan Lilov","Blanka","Reiner Herkenoff","Daniel Octappen"],"places":["Herkenoff malikânesi","Balahnur","Nasihir","Ark Armatech"],"factions":["Herkenoff ailesi","Pox Masters","The Last Bad Decision","Cadılar"],"cons":"Herkenoff'un liderliği çöker; Reiner ölür. Ayrton iki sinomorph'unu kaybeder ama abisi Daniel'i geri kazanır. Trader'a olan borçları artar.","major":true,"src":["Ayrton Octappen hikâyesi"],"unc":false,"note":null,"era":"dusus","tier":"modern","img":{"src":"assets/art/42_Ayrton_Octappen_2.webp","w":853,"h":1280,"kind":"user"}},{"o":144,"date":"Balahnur'un yanışı sırasında","big":"Balahnur'un yanışı sırasında","num":false,"title":"Arrowhul'a uçuş ve Revalor'un düşmüş meleği yenmesi","desc":"Aldric, River ve Serylda ile Arrowhul'a uçar (1 günlük yolculuk) ve Kral Revalor'u ikna eder. Revalor, Üçlü İttifak adına Balahnur'a yardım gönderir. Revalor bizzat Balahnur'a gelir, düşmüş meleği yener ve ayrılır. Melek Arrowhul'da değil Balahnur'da yenilmiştir.","chars":["Aldric Vorn Arkwright","River Lane","Serylda","Revalor Olawarin"],"places":["Arrowhul","Balahnur"],"factions":["Üçlü İttifak","Elfler"],"cons":"Düşmüş melek yenilir ve elf birlikleri Balahnur'a gelir. Aldric ile Revalor arasındaki doğrudan bağ kurulur; Aldric'in sonraki mektubundaki minnet borcunun kaynağı budur.","major":true,"src":["FRP Notları","Kısa Süren Bir Zafer"],"unc":false,"note":null,"era":"dusus","tier":"modern","img":{"src":"assets/art/45_Arrowhul_TahtOdasi.webp","w":1280,"h":720,"kind":"user"}},{"o":145,"date":"Meleğin yenilgisinden sonraki haftanın 3. günü","big":"Meleğin yenilgisinden…","num":false,"title":"'Kısa Süren Bir Zafer'","desc":"Meleğin yenilgisinden sonraki haftanın üçüncü günüdür. Elf birlikleri yaralıları tedavi eder; Julius hâlâ kayıptır. Aldric bir succubus'u Ark Armatech'te tutsak tutar. Saint Antonio kilisesinde portal yoluyla bir kurtarma yapılır. Hikâye Aldric ile River'ın Ark Armatech'teki bir gecesiyle sürer (bölüm I ve IV–VII yetişkin içeriklidir; yalnızca olay düzeyinde anılır).","chars":["Aldric Vorn Arkwright","River Lane","Murat Bey","Serylda","Daria Blackwood","Gideon Blackwood"],"places":["Balahnur","Ark Armatech","Saint Antonio kilisesi"],"factions":["Elfler","Ark Armatech","Üçlü İttifak"],"cons":"Kısa bir nefes alma dönemi; elfler şehirdedir ama Julius kayıptır ve tehdit bitmemiştir.","major":true,"src":["Kısa Süren Bir Zafer","Olay özetleri"],"unc":false,"note":null,"era":"dusus","tier":"modern","img":{"src":"assets/art/30_ArkArkmatech_SavasSonrasi_Gece.webp","w":1280,"h":548,"kind":"user"}},{"o":146,"date":"Meleğin yenilgisinden 2 gün sonra","big":"Meleğin yenilgisinden 2 gün…","num":false,"title":"Düşmüş melek dirilir; cüceler gelir","desc":"Düşmüş melek iki gün sonra cadılar tarafından diriltilir ve şehrin kalanını yakar. Oburluk cadısı kandırılır; cadılar Girift Alem'deki tutulma yerinde Inu olayını araştırmak ister. Cüceler Ark Armatech'in altından çıkar.","chars":["Düşmüş melek","Oburluk cadısı","Aldric Vorn Arkwright"],"places":["Balahnur","Ark Armatech","Girift Alem"],"factions":["Cadılar","Cüceler"],"cons":"Balahnur'un kalanı da yanar; kısa süren zafer biter. Cücelerin tünelleri tahliyenin yolunu açar.","major":true,"src":["FRP Notları"],"unc":false,"note":null,"era":"dusus","tier":"modern","img":{"src":"assets/art/32_E4_Kalkis.webp","w":1280,"h":548,"kind":"user"}},{"o":147,"date":"Tahliye öncesi","big":"Tahliye öncesi","num":false,"title":"Julius geri alınır","desc":"Aldric, prensin ve Indomitable Prime'ın yerini cadılara vererek Julius'u geri alır; Julius'un parmağı kesiktir. Julius Vane VIII 'Home Tonight' anlatımına göre Aldric, Julius'u Melankoli Cadısı'nın yanından uçarak alır. Julius'un sesi günlerce şarkı söylemekten geçici olarak gitmiştir.","chars":["Aldric Vorn Arkwright","Julius Vane","Melankoli Cadısı","Prens"],"places":["Balahnur"],"factions":["Cadılar","The Last Bad Decision"],"cons":"Julius ekibe döner ama yaralı ve geçici olarak sessizdir. Prensin ve Indomitable Prime'ın yeri cadılara verilmiştir; prens Balahnur'da cadılarla kalacaktır.","major":true,"src":["FRP Notları","Yük Dağılımı","Julius Vane hikâyesi"],"unc":false,"note":null,"era":"dusus","tier":"modern","img":{"src":"assets/art/04_Aldric_Aerofall_Open.webp","w":1024,"h":572,"kind":"user"}},{"o":148,"date":"Tahliye gecesi","big":"Tahliye gecesi","num":false,"title":"Korsan saldırısı (Amanar) ve büyük tahliye","desc":"Tam tahliye sırasında korsanlar, dev deniz yılanına benzeyen yaratık Amanar ile Balahnur'a saldırır. Aldric, ekip ve ~500 bin kişi tam bu anda kaçar. Bunlar büyük olasılıkla Revalor'un sözünü ettiği, 'güneyde devasa bir deniz yaratığına sahip' ve kadim elf elementallerini toplayan korsanlardır (çıkarım). Tahliye cüce tünelleri ve 2 portal üzerinden yapılır (Strombaht ya da uzak kıtadaki eski boş elf şehri). ~500 bin kişi, Aldric'in 100 uçan gemisi ve sökülmüş Ark Armatech binası tünellerden götürülür. Çoğunluk ve The Last Bad Decision ekibi elf şehrini seçer; kalanlar ve prens cadılarla Balahnur'da kalır.","chars":["Aldric Vorn Arkwright","Amanar","Korsanlar","Prens"],"places":["Balahnur","Cüce tünelleri","Strombaht","Elf şehri (Mital Alari)"],"factions":["Korsanlar","Cüceler","Elfler","The Last Bad Decision","Ark Armatech","Cadılar"],"cons":"Balahnur terk edilir; ~500 bin kişi ve Ark Armatech elf şehrine taşınır. Prens ve kalanlar cadıların yönetiminde kalır. 'Balahnur'a dönüp kalanları kurtarmak' güncel yayın ana hedefi olur.","major":true,"src":["FRP Notları","Ayrton Octappen hikâyesi"],"unc":true,"note":"Korsanların kimliği çıkarım; 'Amanar' yerel dosyalarda geçmiyor.","era":"dusus","tier":"modern","img":{"src":"assets/art/13_KiyiTarafi.webp","w":1280,"h":548,"kind":"user"}},{"o":149,"date":"Tahliye ile şimdi arası","big":"Tahliye ile şimdi arası","num":false,"title":"Mital Alari'ye varış","desc":"~500 bin kişi elf ve cüce yardımıyla elf şehri Mital Alari'ye ulaşır. Yolculuğun kendisi yazılı değil; Julius VIII'e göre cücelerle portaldan geçilir.","chars":["Aldric Vorn Arkwright","The Last Bad Decision"],"places":["Mital Alari"],"factions":["Elfler","Cüceler","The Last Bad Decision","Ark Armatech"],"cons":"Balahnur halkı elflerle karışık bir kıyı şehrinde yaşamaya başlar; bu birlikte yaşam sorunları doğuracaktır.","major":true,"src":["Julius Vane hikâyesi"],"unc":false,"note":null,"era":"tahliye","tier":"modern","img":{"src":"assets/art/10_ArkArmatech_Elf.webp","w":1280,"h":548,"kind":"user"}},{"o":150,"date":"Tahliye ile şimdi arası (elf şehri sahili)","big":"Tahliye ile şimdi arası","num":false,"title":"Trader zamanı durdurur; Ayrton'un düğünü","desc":"Trader elf şehri sahilinde zamanı 24 saat durdurur. Bu sürede Ayrton; Levi, Rem, Ram ve Omux ile, yani dördüyle evlenir. Ayrton müzik için Julius'tan yardım ister ve düğün alanını birlikte hazırlarlar. Ayrton'un abisi Daniel hayattadır ve Ark Armatech'tedir.","chars":["Ayrton Octappen","Levi","Rem","Ram","Omux","Trader","Julius Vane","Daniel Octappen"],"places":["Mital Alari sahili"],"factions":["The Last Bad Decision"],"cons":"Ayrton'un ilişkileri evlilikle resmîleşir; ekibin nadir mutlu anlarından biridir.","major":true,"src":["Julius Vane hikâyesi","Ayrton Octappen hikâyesi"],"unc":false,"note":null,"era":"tahliye","tier":"modern","img":null},{"o":151,"date":"Tahliye ile şimdi arası","big":"Tahliye ile şimdi arası","num":false,"title":"Murat Bey porsuk olur","desc":"Murat Bey bir Inu'ya (yaratık) dönüşmüş ve tekrar insana dönememiştir; şu an bir porsuktur. Ark Armatech'teki yokluğunun sebebi budur. Balahnur'un düşüşünde işçilerin Inu'ya dönüşmeye başladığı yazılıdır; Murat Bey 'Kısa Süren Bir Zafer'de hâlâ insandır.","chars":["Murat Bey"],"places":["Mital Alari","Ark Armatech"],"factions":["Ark Armatech"],"cons":"Ark Armatech'in yönetimi Aldric'e kalır (ElfAdası Bölüm 1).","major":true,"src":["FRP Notları"],"unc":false,"note":null,"era":"tahliye","tier":"modern","img":{"src":"assets/art/31_E1_MuratbeyKapida.webp","w":1280,"h":548,"kind":"user"}},{"o":152,"date":"Tahliye ile şimdi arası","big":"Tahliye ile şimdi arası","num":false,"title":"Xar'koth ekipten ayrılır","desc":"Xar'koth Val'in ekipten ayrılır; bazı kayıtlarda öldüğü yazılıdır.","chars":["Xar'koth Val'in"],"places":[],"factions":["The Last Bad Decision"],"cons":"Narnia'ya geçişi sağlayan hiçlik portalı ustası artık ekipte değildir.","major":false,"src":[],"unc":false,"note":null,"era":"tahliye","tier":"modern","img":null},{"o":153,"date":"Tahliye ile şimdi arası","big":"Tahliye ile şimdi arası","num":false,"title":"Tom şehir muhafızlarının kaptanı olur","desc":"Gideon'un askeri Tom, şehir muhafızlarının kaptanı olur.","chars":["Tom"],"places":["Mital Alari"],"factions":["Şehir muhafızları"],"cons":"Tom yeni şehirde düzenin sorumlularından biri olur.","major":false,"src":[],"unc":false,"note":null,"era":"tahliye","tier":"modern","img":null},{"o":154,"date":"Elf şehrindeki ilk sabah","big":"Elf şehrindeki ilk sabah","num":false,"title":"Julius maceracı loncasını kurar","desc":"Elf şehrindeki ilk sabah Julius bir maceracı loncası kurar. Kuralları: 'Siviller önce gelir / Hiçbir üye geride bırakılmaz / Her görev gerçekte olduğu gibi kaydedilir.' Bu dönemde (Julius Vane VI–IX) Julius ile Serylda arasındaki gizli ilişki/olay sürer; olay gizli tutulur ve ortaya çıkması Aldric ile Julius arasında ölümcül bir kırılmaya yol açabilecek niteliktedir (ayrıntı kayıtlarda yer almaz).","chars":["Julius Vane","Serylda"],"places":["Mital Alari"],"factions":["Julius'un maceracı loncası"],"cons":"Lonca, Julius'un sonraki trajedisinin (üyelerin Nyxara'ya feda edilmesi) sahnesi olur.","major":true,"src":["Julius Vane hikâyesi"],"unc":false,"note":null,"era":"tahliye","tier":"modern","img":{"src":"assets/art/19_JuliusVane.webp","w":557,"h":821,"kind":"user"}},{"o":155,"date":"Mital Alari — gelişten bir süre sonra","big":"Mital Alari","num":false,"title":"Yük Dağılımı (Aldric'in günlüğü)","desc":"Aldric'in günlüğü. Yeni Ark Armatech binası ayakta ama bitmemiştir; Balahnur'dan gelenler henüz yerleşmemiştir. Aldric; Julius takasını, River'ın cadılığını ve Sedonia meselesini, Serylda'ya duyduğu babalık duygularını ve ölümsüzlüğünü itiraf eder. Cedric avından sonra Levi ile Tom'un ondan uzaklaşmasını anladığını da yazar.","chars":["Aldric Vorn Arkwright","Julius Vane","River Lane","Serylda","Levi","Tom"],"places":["Mital Alari","Ark Armatech"],"factions":["Ark Armatech"],"cons":"Aldric'in iç yükleri (suçluluk, ölümsüzlük, babalık) açıkça ortaya konur; ElfAdası hikâyesinin duygusal zemini kurulur.","major":true,"src":["Yük Dağılımı"],"unc":false,"note":null,"era":"elfadasi","tier":"modern","img":{"src":"assets/art/09_ArkArmatechNew.webp","w":1280,"h":720,"kind":"user"}},{"o":156,"date":"Günlükten 14 gün sonra","big":"Günlükten 14 gün sonra","num":false,"title":"ElfAdası Bölüm 1: yeniden kuruluş ve ilk 'gece cezası'","desc":"Cüceler Ark Armatech'i Balahnur'dan getirilen numaralı taşlarla yeniden kurar. Murat Bey yoktur ve yönetim Aldric'tedir. İşçi krizi, teslimat ve erzak sorunları yaşanır; insanlar hayvana dönüşmektedir. Aldric Vindicator'la şehrin üstünde uçar. Kıyıya yakın bir çatıda içerken bir elf kadına saldıran bir adamı vahşice öldürür: ilk 'gece cezası'. Serylda'nın şifa gücü görünür. River işçi ilanı hazırlar; Serylda'nın eğitimi ertesi gün başlayacaktır.","chars":["Aldric Vorn Arkwright","Serylda","River Lane"],"places":["Mital Alari","Ark Armatech"],"factions":["Cüceler","Ark Armatech"],"cons":"Aldric gece kendi adaletini uygulamaya başlar. Ark Armatech'in yükü tamamen Aldric'in omuzlarına biner ve Serylda'nın eğitimi başlar.","major":true,"src":["ElfAdası"],"unc":false,"note":null,"era":"elfadasi","tier":"modern","img":{"src":"assets/art/08_Ark_Armatech_Cati_Gece.webp","w":1280,"h":720,"kind":"user"}},{"o":157,"date":"Eğitimin 5. günü (fırtınalı bir Çarşamba)","big":"Eğitimin 5. günü","num":false,"title":"ElfAdası Bölüm 2: Girift Çığlığı","desc":"Ark Armatech binası tamamlanır; Order of the Emerald Eye zırhları ve Ark Drive motorları seri üretimdedir. Elf portalları 500 bin kişiye yetmez, kuyruklarda kavga çıkar; Gideon ulaşım altyapısını Ark Armatech'e verir. Daria Blackwood ile PrideBreaker tamamlanır. Grafted eğitim salonunda Serylda'nın 'Girift Çığlığı' ortaya çıkar; istem dışı bir zihin kontrolü belirtisi görülür (Veyr, Hound'a ateş eder).","chars":["Aldric Vorn Arkwright","Serylda","Gideon Blackwood","Daria Blackwood","Veyr","Hound"],"places":["Mital Alari","Ark Armatech","Grafted eğitim salonu"],"factions":["Ark Armatech","Order of the Emerald Eye","The Grafted"],"cons":"Ark Armatech yeni şehirde tam kapasiteye ulaşır. Serylda'nın gücü tehlikeli bir boyuta (istem dışı zihin kontrolü) geçer; bu, Nyxara'nın onu 'cadıların aradığı değerli kız' diye anmasıyla ilişkilenir.","major":true,"src":["ElfAdası"],"unc":false,"note":null,"era":"elfadasi","tier":"modern","img":{"src":"assets/art/21_Order_Of_The_Emerald_Eye.webp","w":1254,"h":1254,"kind":"user"}},{"o":158,"date":"Gelişten haftalar sonra (dolunay)","big":"Gelişten haftalar sonra","num":false,"title":"ElfAdası Bölüm 3: kaçak teslimat baskını","desc":"İnsanlar elf şehrini 'Balahnur'a çevirmektedir: kadim ağaçlar kesilir, elflere sarkıntılık edilir, pislik artar. Aldric ile Gideon konseyde tartışır. Aldric uykusuz gecelerde suçluları 'cezalandırır'. Kaçak bir uyuşturucu teslimatına baskın yapar; çetede Ark Armatech zırhlı, Emerald Eye üniformalı, yozlaşmış bir Gideon askeri vardır. Aldric artificier büyüsüyle mermileri durdurur, zırhı adamın üzerinde küçülterek onu öldürür ve teslimatı yakar. (Bölüm yarım kalmıştır; 'Rahatlamıştı,' diye bitiyor.)","chars":["Aldric Vorn Arkwright","Gideon Blackwood"],"places":["Mital Alari"],"factions":["Ark Armatech","Order of the Emerald Eye","Pox Masters"],"cons":"İnsan–elf gerilimi tırmanır. Ark Armatech teknolojisinin suçlu ellere geçtiği anlaşılır; Aldric'in gece adaleti daha karanlık bir hal alır.","major":true,"src":["ElfAdası"],"unc":true,"note":"Bölüm yarım kalmış.","era":"elfadasi","tier":"modern","img":{"src":"assets/art/38_AldricwNewVindicatorDesignByRiver.webp","w":853,"h":1280,"kind":"user"}},{"o":159,"date":"Aynı dönem (Bölüm 3 ile eşzamanlı)","big":"Aynı dönem","num":false,"title":"Julius ofisine kapanıp içer","desc":"Julius annesini (Hundred Blades kurbanı) bir kampta ölü bulmuştur. Lonca ofisine kilitlenip haftalarca içer ve emirleri kapının altından verir. Lonca Glasswood'un kuzeyindedir; korku simülasyonu salonunu Julius kurmuştur. Nerissa simülasyonları yönetir, Mara ekipleri seçer, Jorge görevleri planlar, Vince yaralılara bakar, Gromur kalkancıdır, Sasha iz sürücüdür. Serylda yemek ve şarkı getirip ona annesinden söz eder. Üyeler onunla yüzleşir; Julius Mara'ya şişe fırlatır, Gromur kalkanıyla durdurur. Bu öfkeyi Nyxara körükler (Hollow Voice).","chars":["Julius Vane","Nerissa","Mara","Jorge","Vince","Gromur","Sasha","Serylda","Nyxara"],"places":["Mital Alari","Glasswood'un kuzeyi","Lonca ofisi"],"factions":["Julius'un maceracı loncası","The Hundred Blades","Nyxara"],"cons":"Julius ile loncası arasındaki güven kırılır; Nyxara'nın etkisi en tehlikeli seviyeye ulaşır ve lonca üyelerinin feda edilmesine giden yol açılır.","major":true,"src":["Julius Vane hikâyesi"],"unc":false,"note":null,"era":"elfadasi","tier":"modern","img":null},{"o":160,"date":"Mital Alari dönemi — ElfAdası Bölüm 3'ten sonra, gece yarısından sonra","big":"Mital Alari dönemi","num":false,"title":"Aldric'in Revalor'a mektubu","desc":"Mital Alari kıyısında, Ark Armatech'in üst katında, gece yarısından sonra Aldric iki taslağı yaktıktan sonra Revalor'a üçüncü sürüm mektubunu yazar. Minnet ve zarar: Balahnur'un göğünü açması, tahliye ve Amanar için teşekkür eder; insanların şehre verdiği zararı (kesilen ağaçlar, kaçak sandıklar) anar. Asıl istek: kıyamet saati için (Ölüm öldürmeye karar verirse ya da cadılar savaşı kazanırsa) zamanın ve mekânın dışında bir vadi. İçinde zaman akar, atla birkaç saatte geçilebilir; çiftlik evi, kuyu, çayır, tarla ve dönen mevsimler vardır; yalnızca Aldric girip çıkabilecek ve yalnızca o bilecektir. Kendi denemeleri 'sınırda' kırılmıştır (zamana tabi malzemeyle zaman dışı duvar yapılamaz); Serylda'nın kapılarını 'hiçliğe açıldıkları' için reddeder. Kâtip Pirdeviz'den aldığı ölümsüzlüğün bir yük olduğunu, zamanın dışında onun sonsuzluğuyla River'ın ve Serylda'nın ömrünün aynı ölçüye gelip gelemeyeceğini sorar. Barışbozan yüzüğünün aileyi öldüren adamdan alındığını, anısı için takıldığını, gerçek anlaşılınca River için yakıldığını ve sağ elinde yanık izi olduğunu itiraf eder. Bedeli önceden kabul eder; Ark Armatech Üçlü İttifak'ın emrindedir. River mektuptan habersizdir; cevap yalnızca Aldric'e gelmelidir. Son olarak Aerofall Trimatus'la uçarken Ölüm'ü bir taş sürükleyerek doğuya yürürken gördüğünü ve taşın sesinin kafasından çıkmadığını yazar; Ölüm'ü durdurmanın yolu varsa Ark Armatech yanındadır. İmza: 'Aldric Vorn Arkwright, Ark Armatech'in Kurucusu'.","chars":["Aldric Vorn Arkwright","Revalor Olawarin","River Lane","Serylda","Katip Pirdeviz","Ölüm"],"places":["Mital Alari","Ark Armatech","Arrowhul"],"factions":["Ark Armatech","Üçlü İttifak","Elfler"],"cons":"Revalor'un cevabı beklenir; Ölüm'ün doğuya yürüyüşü yeni bir tehdit olarak ufukta belirir.","major":true,"src":["Aldric’in Revalor’a mektubu"],"unc":false,"note":null,"era":"elfadasi","tier":"modern","img":{"src":"assets/art/26_Aldric_To_Revalor_Mektup_Photo1.webp","w":1280,"h":548,"kind":"user"}},{"o":161,"date":"Mital Alari dönemi — Revalor mektubundan sonra","big":"Mital Alari dönemi","num":false,"title":"Julius altı lonca üyesini Nyxara'ya götürür","desc":"Julius ofisten çıkar ve simülasyonda Hundred Blades'i gösterir. Sasha, Jorge, Mara, Gromur, Vince ve Nerissa'yı 'Hundred Blades izi' bahanesiyle Glasswood'un ötesindeki Nyxara mağarasına götürür: 'Julius onları feda etmeye götürüyordu.' XI'de tek başına döner ve Nyxara'dan aldığı yeni güçle loncayı bir yalana inandırır. Kayıtlarda geçen '6–7 masum' büyük olasılıkla bu altı kişidir.","chars":["Julius Vane","Sasha","Jorge","Mara","Gromur","Vince","Nerissa","Nyxara"],"places":["Glasswood'un ötesi","Nyxara'nın mağarası"],"factions":["Julius'un maceracı loncası","Nyxara"],"cons":"Altı lonca üyesi feda edilir; Julius güçlenir ama duygularını daha da kaybeder. Bu, Gideon'un onu hapsedecek olmasının temel nedenlerinden biridir.","major":true,"src":["Julius Vane hikâyesi"],"unc":false,"note":null,"era":"julius","tier":"modern","img":{"src":"assets/art/19_JuliusVane.webp","w":557,"h":821,"kind":"user"}},{"o":162,"date":"Mital Alari dönemi — Revalor mektubundan sonra, iki hafta sonra","big":"Mital Alari dönemi","num":false,"title":"The Hundred Blades katliamı","desc":"İki hafta sonra Hundred Blades kampının yeri bulunur. Gideon ve Aldric'in desteğiyle haydutların çoğu katledilir; esirleri Julius melodisiyle öldürür. Anastasia kurtarılır. Kayıtlarda geçen '100 haydut' bu olaydır.","chars":["Julius Vane","Gideon Blackwood","Aldric Vorn Arkwright","Anastasia"],"places":["Hundred Blades kampı"],"factions":["The Hundred Blades","The Last Bad Decision"],"cons":"Julius'un intikamı alınır ve Anastasia geri döner. Ancak esirlerin melodiyle öldürülmesi Julius'un karanlığa düştüğünü gösterir.","major":true,"src":["Julius Vane hikâyesi"],"unc":false,"note":null,"era":"julius","tier":"modern","img":{"src":"assets/art/17_Gideon_v2.webp","w":960,"h":1280,"kind":"user"}},{"o":163,"date":"Mital Alari dönemi — Revalor mektubundan sonra","big":"Mital Alari dönemi","num":false,"title":"12 şarkı","desc":"Julius duygularını kaybettiğini fark eder; iblis sayısı olan 13'e yaklaşmaktadır. Anastasia'nın Julius'un koluna girdiğini gören Serylda'nın kalbi sızlar. Julius, Anastasia ile birlikte Nyxara'yı öldürmeye karar verir.","chars":["Julius Vane","Anastasia","Serylda","Nyxara"],"places":["Mital Alari"],"factions":["Nyxara"],"cons":"Julius anlaşmayı bozma kararı alır; 13. şarkı tuzağına giden son adım atılır.","major":false,"src":["Julius Vane hikâyesi"],"unc":false,"note":null,"era":"julius","tier":"modern","img":null},{"o":164,"date":"Mital Alari dönemi — Revalor mektubundan sonra","big":"Mital Alari dönemi","num":false,"title":"Nyxara'nın ini: Julius kendi boğazını keser, Nyxara ölür","desc":"Julius, Anastasia, Gideon ve Aldric Nyxara'nın inine gider; Serylda onları gizlice izlemiştir (Nyxara onu 'cadıların aradığı o değerli, masum kız' diye anar). Nyxara 13. şarkıyı tamamlamaya çalışır ve herkesi diz çöktürür. Julius anlaşmayı bozmak için kılıcı kendi boğazına saplar; Gideon ve Aldric Nyxara'yı öldürür.","chars":["Julius Vane","Anastasia","Gideon Blackwood","Aldric Vorn Arkwright","Serylda","Nyxara"],"places":["Nyxara'nın ini"],"factions":["Nyxara","The Last Bad Decision","Cadılar"],"cons":"Nyxara ölür ve anlaşma bozulur. Julius kendini feda ederek ölümün eşiğine gelir. Serylda'nın cadıların aradığı kız olduğu bir iblis tarafından dile getirilir.","major":true,"src":["Julius Vane hikâyesi"],"unc":false,"note":null,"era":"julius","tier":"modern","img":null},{"o":165,"date":"Mital Alari dönemi — Revalor mektubundan sonra","big":"Mital Alari dönemi","num":false,"title":"Silent Voice","desc":"Serylda Julius'un yarasını kapatır ama Julius'un ses telleri Nyxara'nın ölümüyle kalıcı olarak yok olur. Julius'un duyguları geri gelir; artık konuşamaz.","chars":["Julius Vane","Serylda"],"places":["Nyxara'nın ini"],"factions":[],"cons":"'Silver Voice' sonsuza dek susar; Julius duygularına kavuşur ama sesini kaybeder.","major":true,"src":["Julius Vane hikâyesi"],"unc":false,"note":null,"era":"julius","tier":"modern","img":null},{"o":166,"date":"Gelecek (henüz anlatılmadı)","big":"Gelecek","num":false,"title":"Gideon Julius'u hapsedecek; Aldric gerçeği öğrenecek","desc":"Gelecekte yaşanacağı belirtilen olay: Gideon Julius'u hapsedecek ve Aldric, Julius'un yaptıklarını (ve Julius ile Serylda arasındaki gizli ilişkiyi) öğrenecektir. Olay henüz anlatılmamıştır; 'XV – by The Eclipse' bölümü taslak hâlindedir. Eski kayıtlardaki 'Julius bir şeytan tarafından kandırılıp 6–7 masum + 100 haydut öldürdü; Gideon hapsetmek üzere' ifadesi bu olaylarla tutarlıdır: 'kandırılma', Nyxara'nın 13. şarkı tuzağı ve Julius'un duygularını sinsice yemesi olarak okunabilir.","chars":["Gideon Blackwood","Julius Vane","Aldric Vorn Arkwright","Serylda"],"places":["Mital Alari"],"factions":["Pox Masters","The Last Bad Decision"],"cons":"Ekip içinde büyük bir kırılma bekleniyor: Julius hapsedilecek, Aldric–Julius ilişkisi sarsılacak.","major":true,"src":[],"unc":true,"note":"Henüz anlatılmadı; planlanmış olay.","era":"julius","tier":"modern","img":null}]};
